package controller;

import constants.Constants;
import dto.LoadReportDTO;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;
import repository.FileBookRepository;
import repository.FileLoanRepository;
import repository.FileMemberRepository;
import repository.IBookRepository;
import repository.ILoanRepository;
import repository.IMemberRepository;
import view.ReportView;

/**
 * KHUNG LAP RAP cua CT Library 1.0 (composition root): tao MOT ban moi kho, roi TRUYEN kho vao
 * cac Controller qua constructor (tiem phu thuoc bang tay — Spring Boot lam dung viec nay
 * bang @Autowired). Day la noi DUY NHAT biet kho nam o dau: chang sau doi 3 dong new
 * FileXxxRepository thanh JdbcXxxRepository (PostgreSQL), khong lop nao khac doi.
 * Ba Controller cung nhin MOT kho sach: muon o LoanController thi bao cao thay ngay.
 *
 * @author CuongThai Academy
 */
public class AppController {

    // Kho tai lieu dung chung
    private IBookRepository bookRepository;

    // Kho thanh vien dung chung
    private IMemberRepository memberRepository;

    // Kho luot muon dung chung
    private ILoanRepository loanRepository;

    // Dieu phoi tai lieu (tim, them)
    private BookController bookController;

    // Dieu phoi thanh vien (them)
    private MemberController memberController;

    // Dieu phoi muon - tra - no
    private LoanController loanController;

    // Dieu phoi bao cao
    private ReportController reportController;

    // Man hinh in ket qua nap
    private ReportView reportView;

    // Mo 3 kho (nap 3 tep), roi lap 4 Controller tren cung cac kho do
    public AppController() {
        bookRepository = new FileBookRepository(Constants.BOOK_FILE_PATH);
        memberRepository = new FileMemberRepository(Constants.MEMBER_FILE_PATH);
        loanRepository = new FileLoanRepository(Constants.LOAN_FILE_PATH);
        bookController = new BookController(bookRepository);
        memberController = new MemberController(memberRepository);
        loanController = new LoanController(bookRepository, memberRepository, loanRepository);
        reportController = new ReportController(bookRepository, memberRepository,
                loanRepository);
        reportView = new ReportView();
    }

    // In ket qua nap: so ban ghi moi tep + moi dong hong cua ca 3 tep
    public void showLoadReport() {
        // Gom so lieu va cau bao cua 3 kho
        LoadReportDTO loadReport = new LoadReportDTO();
        loadReport.setItemCount(bookRepository.countItems());
        loadReport.setMemberCount(memberRepository.countMembers());
        loadReport.setLoanCount(loanRepository.countLoans());
        List<String> errorList = new ArrayList<>();
        errorList.addAll(bookRepository.findLoadErrorList());
        errorList.addAll(memberRepository.findLoadErrorList());
        errorList.addAll(loanRepository.findLoadErrorList());
        loadReport.setErrorList(errorList);
        reportView.showLoadReport(loadReport);
    }

    // Dat ngay lam viec cho moi noi dung no (muon, tra, qua han)
    public void setWorkingDate(LocalDate workingDate) {
        loanController.setWorkingDate(workingDate);
        reportController.setWorkingDate(workingDate);
    }

    // Tra ve Controller tai lieu
    public BookController getBookController() {
        return bookController;
    }

    // Tra ve Controller thanh vien
    public MemberController getMemberController() {
        return memberController;
    }

    // Tra ve Controller muon - tra - no
    public LoanController getLoanController() {
        return loanController;
    }

    // Tra ve Controller bao cao
    public ReportController getReportController() {
        return reportController;
    }
}

package controller;

import constants.Message;
import dto.BookRequestDTO;
import dto.BookResponseDTO;
import exceptions.LibraryException;
import java.util.List;
import repository.IBookRepository;
import service.BookService;
import view.BookView;

/**
 * Dieu phoi yeu cau ve tai lieu: GIU kho (goi CRUD), dua du lieu cho Service, dua ket qua
 * cho View. Khong import model — chi biet DTO.
 *
 * @author CuongThai Academy
 */
public class BookController {

    // Kho tai lieu (nhan tu AppController)
    private IBookRepository bookRepository;

    // Nghiep vu tim + sap
    private BookService bookService;

    // Man hinh tai lieu
    private BookView bookView;

    // Nhan kho dung chung, tao service va view
    public BookController(IBookRepository bookRepository) {
        this.bookRepository = bookRepository;
        bookService = new BookService();
        bookView = new BookView();
    }

    // Tim tai lieu theo ten
    public void searchItems(String keyword) {
        // Ket qua da loc, sap, danh so
        List<BookResponseDTO> foundList = bookService.searchByTitle(
                bookRepository.findAll(), keyword);

        // Khong thay thi 1 cau; thay thi so luong + bang
        if (foundList.isEmpty()) {
            bookView.showMessage(String.format(Message.NOT_FOUND_TITLE, keyword));
            return;
        }
        bookView.showMessage(String.format(Message.FOUND_TITLE, foundList.size(), keyword));
        bookView.showItemList(foundList);
    }

    // Them tai lieu (phieu da kiem tung o): kho cap ma, ghi tep
    public void addItem(BookRequestDTO bookRequestDTO) {
        // Kho cap ma; trung khoa hoac loi ghi tep thi in cau bao
        try {
            String newId = bookRepository.addItem(bookRequestDTO);
            bookView.showMessage(String.format(Message.SUCCESS_ADD_ITEM, newId,
                    bookRequestDTO.getTitle(), bookRepository.countItems()));
        } catch (LibraryException e) {
            // Loi nao cung mang san cau bao tieng Viet
            bookView.showMessage(e.getMessage());
        }
    }
}

package controller;

import constants.Message;
import dto.BookResponseDTO;
import dto.LoanRecordDTO;
import dto.LoanRequestDTO;
import dto.MemberResponseDTO;
import dto.PaymentRequestDTO;
import exceptions.LibraryException;
import java.time.LocalDate;
import java.util.List;
import repository.IBookRepository;
import repository.ILoanRepository;
import repository.IMemberRepository;
import service.LoanService;
import utils.FormatUtils;
import view.LoanView;

/**
 * Dieu phoi MUON - TRA - DONG PHAT va the thanh vien. GIU ca 3 kho (CRUD o day), dua du
 * lieu cho LoanService kiem luat / tinh phat, roi ghi ket qua vao kho va dua cau cho View.
 * Moi viec: lay du lieu -> Service quyet -> kho ghi -> View in; buoc nao nem LibraryException
 * thi cac buoc SAU khong chay (khong tru ban oan, khong cong no oan). Khong import model.
 *
 * @author CuongThai Academy
 */
public class LoanController {

    // Kho tai lieu
    private IBookRepository bookRepository;

    // Kho thanh vien
    private IMemberRepository memberRepository;

    // Kho luot muon
    private ILoanRepository loanRepository;

    // Luat muon - tra - phat
    private LoanService loanService;

    // Man hinh muon - tra - no
    private LoanView loanView;

    // Nhan 3 kho dung chung, tao service va view
    public LoanController(IBookRepository bookRepository, IMemberRepository memberRepository,
            ILoanRepository loanRepository) {
        this.bookRepository = bookRepository;
        this.memberRepository = memberRepository;
        this.loanRepository = loanRepository;
        loanService = new LoanService();
        loanView = new LoanView();
    }

    // Dat ngay lam viec
    public void setWorkingDate(LocalDate workingDate) {
        loanService.setWorkingDate(workingDate);
    }

    // The thanh vien: thong tin, no, trang thai the, luot dang mo kem so ngay tre
    public void showMemberCard(String memberId) {
        // Khong co ma thi in cau bao
        try {
            MemberResponseDTO member = findMemberWithLoans(memberId);
            List<LoanRecordDTO> openLoanList = loanRepository.findOpenLoansOfMember(
                    memberId);

            // Ten tai lieu cua tung luot (de in)
            for (LoanRecordDTO loan : openLoanList) {
                loan.setItemTitle(bookRepository.findById(loan.getItemId()).getTitle());
            }
            loanView.showMemberCard(member, loanService.prepareOpenLoans(openLoanList));
        } catch (LibraryException e) {
            // Khong co thanh vien / tai lieu
            loanView.showMessage(e.getMessage());
        }
    }

    // Muon: lay thanh vien + tai lieu, Service kiem 3 luat, kho ghi luot TRUOC roi moi tru ban
    public void borrowItem(LoanRequestDTO loanRequestDTO) {
        // Buoc nao nem loi thi dung, cac buoc sau khong chay
        try {
            MemberResponseDTO member = findMemberWithLoans(loanRequestDTO.getMemberId());
            BookResponseDTO item = bookRepository.findById(loanRequestDTO.getItemId());
            LoanRecordDTO loan = loanService.createLoan(member, item);

            // Dang muon dung tai lieu nay thi kho nem loi trung — chua tru ban nao
            String loanId = loanRepository.addLoan(loan);
            bookRepository.updateCopies(item.getId(), item.getCopies() - 1);
            loanView.showMessage(String.format(Message.SUCCESS_BORROW, loanId, member.getId(),
                    item.getId(), item.getTitle(), FormatUtils.formatDate(loan.getDueDate()),
                    item.getLoanDays(), member.getOpenLoanCount() + 1, member.getMaxLoans(),
                    item.getCopies() - 1));
        } catch (LibraryException e) {
            // Khong co ma, khoa the, qua han muc, het ban, dang muon roi, loi ghi tep
            loanView.showMessage(e.getMessage());
        }
    }

    // Tra: tim luot dang mo, Service tinh tre + phat, kho dong luot, cong ban, cong no
    public void returnItem(LoanRequestDTO loanRequestDTO) {
        // TODO DA.3 — giong borrowItem: trong 1 khoi try (catch LibraryException -> View):
        //   thanh vien + tai lieu tu kho, luot dang mo (loanRepository.findOpenLoan), dien
        //   lateFeePerDay cua tai lieu vao luot, loanService.closeLoan, no moi = addFine;
        //   roi GHI 3 kho: closeLoan, updateCopies(+1), updateDebt; in Message.SUCCESS_RETURN
        //   (ten chinh sach: loanService.findPolicyName, trang thai the: describeCard).
        loanView.showMessage(Message.TODO_NOT_DONE);
    }

    // Dong phat: Service tinh no moi (tu choi nop qua no), kho ghi no moi
    public void payFine(PaymentRequestDTO paymentRequestDTO) {
        // Khong co ma, khong no, nop qua no, loi ghi tep
        try {
            MemberResponseDTO member = memberRepository.findById(
                    paymentRequestDTO.getMemberId());
            int newDebt = loanService.payFine(member, paymentRequestDTO.getAmount());
            memberRepository.updateDebt(member.getId(), newDebt);
            member.setDebt(newDebt);
            loanView.showMessage(String.format(Message.SUCCESS_PAY,
                    FormatUtils.formatMoney(paymentRequestDTO.getAmount()), member.getId(),
                    FormatUtils.formatMoney(newDebt), describeCard(member)));
        } catch (LibraryException e) {
            // Cau bao cua chinh loi do
            loanView.showMessage(e.getMessage());
        }
    }

    // Thanh vien kem so luot dang mo va co khoa the (Controller dien tu kho + luat Service)
    private MemberResponseDTO findMemberWithLoans(String memberId) throws LibraryException {
        // Thanh vien tu kho
        MemberResponseDTO member = memberRepository.findById(memberId);
        member.setOpenLoanCount(loanRepository.findOpenLoansOfMember(memberId).size());
        member.setLocked(loanService.isLocked(member));
        return member;
    }

    // Chu trang thai the sau khi no thay doi
    private String describeCard(MemberResponseDTO member) {
        // Khoa hay mo theo luat cua Service
        if (loanService.isLocked(member)) {
            return Message.CARD_LOCKED;
        }
        return Message.CARD_ACTIVE;
    }
}

