package exceptions;

/**
 * Lop CHA cua moi loi NGHIEP VU cua CT Library 1.0 (khong tim thay, het ban, qua han muc,
 * the bi khoa, loi luu tep...). La ngoai le CHECKED (extends Exception): javac BUOC noi goi
 * phai bat hoac khai throws, vi day la ket qua co the xay ra va nguoi dung sua duoc.
 * Abstract: khong ai nem "loi thu vien chung chung"; luon nem 1 lop con co ten ro rang.
 * Controller bat ca ho bang 1 khoi catch (LibraryException e) roi dua cau bao cho View.
 *
 * @author CuongThai Academy
 */
public abstract class LibraryException extends Exception {

    // Tao ngoai le kem cau bao loi tieng Viet (lop con goi qua super)
    protected LibraryException(String message) {
        super(message);
    }

    // Tao ngoai le kem cau bao loi + NGUYEN NHAN goc (IOException khi doc/ghi tep)
    protected LibraryException(String message, Throwable cause) {
        super(message, cause);
    }
}

