package model;

import constants.Constants;
import constants.Message;

/**
 * Mot cuon sach: LA MOT (is-a) tai lieu, them ISBN va tac gia.
 * Muon 14 ngay, tre 2000 dong/ngay, khoa chong trung la ISBN.
 * JavaBean: truong private, constructor rong public, getter/setter.
 *
 * @author CuongThai Academy
 */
public class Book extends LibraryItem {

    // Ma ISBN-13 (13 chu so, da bo dau - va dau cach)
    private String isbn;

    // Tac gia da chuan hoa (Title Case)
    private String author;

    // Constructor rong (JavaBean): goi constructor day du voi chuoi rong va so 0
    public Book() {
        this("", "", "", "", 0, 0);
    }

    // Constructor day du; super(...) PHAI la dong dau: dung phan cha truoc, phan con sau
    public Book(String id, String isbn, String title, String author, int year, int copies) {
        super(id, title, year, copies);
        this.isbn = isbn;
        this.author = author;
    }

    // Tra ve ISBN
    public String getIsbn() {
        return isbn;
    }

    // Gan ISBN
    public void setIsbn(String isbn) {
        this.isbn = isbn;
    }

    // Tra ve tac gia (ghi de cau tra loi mac dinh "khong co tac gia" cua LibraryItem)
    @Override
    public String getAuthor() {
        return author;
    }

    // Gan tac gia
    public void setAuthor(String author) {
        this.author = author;
    }

    // So cua loai: TYPE_BOOK
    @Override
    public int getItemType() {
        return Constants.TYPE_BOOK;
    }

    // Loai: Sach
    @Override
    public String getTypeName() {
        return Message.TYPE_BOOK;
    }

    // Ma sach bat dau bang B
    @Override
    public String getIdPrefix() {
        return Constants.BOOK_ID_PREFIX;
    }

    // Sach muon 14 ngay
    @Override
    public int getLoanDays() {
        return Constants.BOOK_LOAN_DAYS;
    }

    // Sach tre 2000 dong/ngay
    @Override
    public int getLateFeePerDay() {
        return Constants.BOOK_LATE_FEE;
    }

    // Chi tiet: tac gia + ISBN
    @Override
    public String getDetail() {
        return String.format(Message.DETAIL_BOOK, author, isbn);
    }

    // Hai cuon cung ISBN la trung
    @Override
    public String getUniqueKey() {
        return String.format(Message.KEY_BOOK, isbn);
    }

    // Cot rieng cua sach trong tep: ISBN roi tac gia
    @Override
    public String[] getExtraValueArray() {
        return new String[] {isbn, author};
    }
}

