package repository;

import constants.Constants;
import constants.Message;
import dto.BookRequestDTO;
import dto.BookResponseDTO;
import dto.CsvRowDTO;
import exceptions.DuplicateKeyException;
import exceptions.InvalidInputException;
import exceptions.ItemNotFoundException;
import exceptions.LibraryException;
import exceptions.StorageException;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import model.Book;
import model.Dvd;
import model.LibraryItem;
import model.Magazine;
import utils.CsvUtils;
import utils.Validation;

/**
 * Kho tai lieu tren tep data/books.csv (UTF-8). Mo kho = NAP tep: moi dong qua CUNG bo kiem
 * Validation nhu ban phim, dong hong bi bo qua kem so dong; moi lan THAY DOI = GHI LAI ca tep
 * (CsvUtils: qua tep tam). Trong bo nho: LinkedHashMap ma -> tai lieu (tim theo ma O(1), giu
 * thu tu) + HashSet khoa chong trung (ISBN, ten + ky so, ten + nam).
 *
 * @author CuongThai Academy
 */
public class FileBookRepository implements IBookRepository {

    // Tai lieu theo ma, giu thu tu them vao
    private Map<String, LibraryItem> itemMap;

    // Khoa chong trung cua moi tai lieu dang co
    private Set<String> uniqueKeySet;

    // Duong dan tep du lieu
    private String filePath;

    // Cau bao luc nap
    private List<String> loadErrorList;

    // Nap thay dong hong ma chua sao luu: lan ghi dau phai giu tep goc thanh .bak
    private boolean isBackupNeeded;

    // So lon nhat da cap (ma moi = so nay + 1, khong dung lai ma da xoa)
    private int lastNumber;

    // Tao kho tren tep va nap ngay (loi nap la cau bao, khong nem)
    public FileBookRepository(String filePath) {
        this.filePath = filePath;
        itemMap = new LinkedHashMap<>();
        uniqueKeySet = new HashSet<>();
        loadErrorList = new ArrayList<>();
        isBackupNeeded = false;
        lastNumber = 0;
        loadFromFile();
    }

    // Moi tai lieu (ban sao), theo thu tu trong tep
    @Override
    public List<BookResponseDTO> findAll() {
        // Danh sach ban sao
        List<BookResponseDTO> resultList = new ArrayList<>();

        // Doi tung model thanh 1 dong DTO
        for (LibraryItem item : itemMap.values()) {
            resultList.add(toResponse(item));
        }
        return resultList;
    }

    // Tim theo ma bang HashMap (khong duyet ca danh sach)
    @Override
    public BookResponseDTO findById(String id) throws ItemNotFoundException {
        return toResponse(findItem(id));
    }

    // Them tai lieu: kiem trung khoa, cap ma theo loai, ghi lai tep
    @Override
    public String addItem(BookRequestDTO bookRequestDTO)
            throws DuplicateKeyException, StorageException {
        // Model moi (chua co ma) de hoi khoa chong trung va tien to ma
        LibraryItem item = createItem(bookRequestDTO);

        // Trung khoa thi tu choi, kho khong doi
        if (uniqueKeySet.contains(item.getUniqueKey())) {
            throw new DuplicateKeyException(String.format(Message.ERROR_DUPLICATE_ITEM,
                    item.getUniqueKey()));
        }

        // Cap ma moi roi them
        lastNumber++;
        item.setId(String.format(Constants.ITEM_ID_FORMAT, item.getIdPrefix(), lastNumber));
        itemMap.put(item.getId(), item);
        uniqueKeySet.add(item.getUniqueKey());
        saveToFile();
        return item.getId();
    }

    // Doi so ban cua 1 tai lieu roi ghi lai tep
    @Override
    public void updateCopies(String id, int copies)
            throws ItemNotFoundException, StorageException {
        findItem(id).setCopies(copies);
        saveToFile();
    }

    // So tai lieu dang co
    @Override
    public int countItems() {
        return itemMap.size();
    }

    // Cau bao luc nap (ban sao)
    @Override
    public List<String> findLoadErrorList() {
        return new ArrayList<>(loadErrorList);
    }

    // Tim model theo ma; khong co thi nem loi kem ma
    private LibraryItem findItem(String id) throws ItemNotFoundException {
        // Tai lieu mang ma nay (null neu khong co)
        LibraryItem item = itemMap.get(id);

        // Khong co ma thi bao
        if (item == null) {
            throw new ItemNotFoundException(String.format(Message.ERROR_ITEM_NOT_FOUND, id));
        }
        return item;
    }

    // Nap tep: moi dong mot khoi try — dong hong chi la 1 cau bao, dong sau van nap
    private void loadFromFile() {
        // Doc moi dong; loi doc that thi ghi cau bao (kho rong)
        try {
            // Cac dong du lieu da tach
            List<CsvRowDTO> rowList = CsvUtils.readRows(filePath, loadErrorList);

            // Doi tung dong thanh model
            for (CsvRowDTO row : rowList) {
                // Mot dong hong: ghi cau bao kem so dong, can sao luu truoc lan ghi dau
                try {
                    loadRow(row);
                } catch (LibraryException e) {
                    // Bo qua dong nay, nap tiep dong sau
                    loadErrorList.add(String.format(Message.ERROR_CSV_LINE, filePath,
                            row.getLineNumber(), e.getMessage()));
                    isBackupNeeded = true;
                }
            }
        } catch (StorageException e) {
            // Khong doc duoc tep: chi bao, chuong trinh van chay voi kho rong
            loadErrorList.add(e.getMessage());
        }
    }

    // Doi 1 dong tep thanh model qua bo kiem Validation; sai dau thi nem dung loi do
    private void loadRow(CsvRowDTO row) throws InvalidInputException, DuplicateKeyException {
        // Cac gia tri cua dong
        List<String> valueList = row.getValueList();

        // Cot dau phai la loai hop le truoc khi dem so cot
        BookRequestDTO request = new BookRequestDTO();
        request.setItemType(Validation.getItemType(valueList.get(Constants.CSV_TYPE_INDEX)));
        int expectedColumns = Constants.BOOK_CSV_COMMON_COLUMNS
                + Constants.BOOK_CSV_EXTRA_COUNT_ARRAY[request.getItemType() - 1];

        // Thieu hay thua cot thi bao so cot can va so cot co
        if (valueList.size() != expectedColumns) {
            throw new InvalidInputException(String.format(Message.ERROR_CSV_COLUMNS,
                    expectedColumns, valueList.size()));
        }

        // Cac cot chung qua dung bo kiem cua ban phim
        String id = Validation.getItemId(valueList.get(Constants.CSV_ID_INDEX));
        request.setTitle(Validation.getTitle(valueList.get(Constants.CSV_TITLE_INDEX)));
        request.setYear(Validation.getYear(valueList.get(Constants.CSV_YEAR_INDEX)));
        request.setCopies(Validation.getCopies(valueList.get(Constants.CSV_COPIES_INDEX)));
        fillExtraColumns(request, valueList);

        // Dung model, roi kiem: tien to ma khop loai, khong trung ma, khong trung khoa
        LibraryItem item = createItem(request);
        item.setId(id);
        checkLoadedItem(item);
        itemMap.put(id, item);
        uniqueKeySet.add(item.getUniqueKey());
        lastNumber = Math.max(lastNumber, Integer.parseInt(id.substring(
                Constants.ID_PREFIX_LENGTH)));
    }

    // Dien cot rieng theo loai (sach: ISBN + tac gia, tap chi: ky so, DVD: so phut)
    private void fillExtraColumns(BookRequestDTO request, List<String> valueList)
            throws InvalidInputException {
        // Gia tri cot rieng dau tien
        String firstExtra = valueList.get(Constants.CSV_EXTRA_INDEX);

        // Moi loai doc cot rieng cua no
        switch (request.getItemType()) {
            // Sach: ISBN roi tac gia
            case Constants.TYPE_BOOK:
                request.setIsbn(Validation.getIsbn(firstExtra));
                request.setAuthor(Validation.getAuthor(
                        valueList.get(Constants.CSV_EXTRA_INDEX + 1)));
                break;
            // Tap chi: ky so
            case Constants.TYPE_MAGAZINE:
                request.setIssueNumber(Validation.getIssueNumber(firstExtra));
                break;
            // DVD: so phut
            default:
                request.setMinutes(Validation.getMinutes(firstExtra));
                break;
        }
    }

    // Kiem tai lieu vua nap: tien to ma dung loai, ma chua co, khoa chua co
    private void checkLoadedItem(LibraryItem item) throws InvalidInputException,
            DuplicateKeyException {
        // Ma B cho sach, T cho tap chi, D cho DVD
        if (!item.getId().startsWith(item.getIdPrefix())) {
            throw new InvalidInputException(String.format(Message.ERROR_ID_PREFIX, item.getId(),
                    item.getTypeName()));
        }

        // Hai dong cung ma
        if (itemMap.containsKey(item.getId())) {
            throw new DuplicateKeyException(String.format(Message.ERROR_DUPLICATE_ID,
                    item.getId()));
        }

        // Hai dong cung khoa (vd cung ISBN)
        if (uniqueKeySet.contains(item.getUniqueKey())) {
            throw new DuplicateKeyException(String.format(Message.ERROR_DUPLICATE_ITEM,
                    item.getUniqueKey()));
        }
    }

    // Phieu -> model dung loai (noi DUY NHAT trong kho hoi loai; sau do moi viec la da hinh)
    private LibraryItem createItem(BookRequestDTO request) {
        // Chon lop con theo loai
        switch (request.getItemType()) {
            // Sach
            case Constants.TYPE_BOOK:
                return new Book(Constants.EMPTY, request.getIsbn(), request.getTitle(),
                        request.getAuthor(), request.getYear(), request.getCopies());
            // Tap chi
            case Constants.TYPE_MAGAZINE:
                return new Magazine(Constants.EMPTY, request.getTitle(), request.getYear(),
                        request.getCopies(), request.getIssueNumber());
            // DVD
            default:
                return new Dvd(Constants.EMPTY, request.getTitle(), request.getYear(),
                        request.getCopies(), request.getMinutes());
        }
    }

    // Ghi lai ca tep: sao luu .bak neu can, roi moi dong mot tai lieu
    private void saveToFile() throws StorageException {
        // Lan ghi dau sau khi nap thay dong hong: giu tep goc
        if (isBackupNeeded) {
            CsvUtils.backupFile(filePath);
            isBackupNeeded = false;
        }

        // Moi tai lieu thanh 1 dong CSV
        List<String> lineList = new ArrayList<>();
        for (LibraryItem item : itemMap.values()) {
            // Moi gia tri rieng mot cot
            lineList.add(toCsvLine(item));
        }
        CsvUtils.writeRows(filePath, Constants.BOOK_CSV_HEADER, lineList);
    }

    // Model -> 1 dong CSV: 5 cot chung + cot rieng (da hinh, khong instanceof)
    private String toCsvLine(LibraryItem item) {
        // Gia tri cac cot theo dung thu tu dong tieu de
        List<String> valueList = new ArrayList<>();
        valueList.add(String.valueOf(item.getItemType()));
        valueList.add(item.getId());
        valueList.add(item.getTitle());
        valueList.add(String.valueOf(item.getYear()));
        valueList.add(String.valueOf(item.getCopies()));

        // Cot rieng do chinh lop con tra loi
        for (String extra : item.getExtraValueArray()) {
            valueList.add(extra);
        }
        return CsvUtils.joinLine(valueList);
    }

    // Model -> ban sao DTO (moi cau tra loi da hinh lay san o day)
    private BookResponseDTO toResponse(LibraryItem item) {
        // Dong ban sao
        BookResponseDTO response = new BookResponseDTO();
        response.setId(item.getId());
        response.setItemType(item.getItemType());
        response.setTypeName(item.getTypeName());
        response.setTitle(item.getTitle());
        response.setYear(item.getYear());
        response.setCopies(item.getCopies());
        response.setDetail(item.getDetail());
        response.setLoanDays(item.getLoanDays());
        response.setLateFeePerDay(item.getLateFeePerDay());
        return response;
    }
}

