/**
 * Kho luot muon tren tep data/loans.csv (UTF-8): ma luot, ma thanh vien, ma tai lieu, ngay
 * muon, han tra, ngay tra (o trong = dang mo), tien phat. Ca lich su nam o day — bao cao top
 * muon va doanh thu phat doc tu no. Trong bo nho: LinkedHashMap ma luot -> luot (giu thu tu)
 * + HashSet "ma thanh vien|ma tai lieu" cua cac luot DANG MO (khong muon trung 1 tai lieu).
 *
 * @author CuongThai Academy
 */
public class FileLoanRepository implements ILoanRepository {

    // Luot muon theo ma, giu thu tu (L0001, L0002, ...)
    private Map<String, Loan> loanMap;

    // Khoa "thanh vien|tai lieu" cua moi luot dang mo
    private Set<String> openKeySet;

    // Duong dan tep du lieu
    private String filePath;

    // Cau bao luc nap
    private List<String> loadErrorList;

    // Nap thay dong hong ma chua sao luu
    private boolean isBackupNeeded;

    // So lon nhat da cap
    private int lastNumber;

    // Tao kho tren tep va nap ngay
    public FileLoanRepository(String filePath) {
        this.filePath = filePath;
        loanMap = new LinkedHashMap<>();
        openKeySet = new HashSet<>();
        loadErrorList = new ArrayList<>();
        isBackupNeeded = false;
        lastNumber = 0;
        loadFromFile();
    }

    // Moi luot muon (ban sao)
    @Override
    public List<LoanRecordDTO> findAll() {
        // Danh sach ban sao
        List<LoanRecordDTO> resultList = new ArrayList<>();

        // Doi tung model thanh DTO
        for (Loan loan : loanMap.values()) {
            resultList.add(toRecord(loan));
        }
        return resultList;
    }

    // Cac luot dang mo cua 1 thanh vien
    @Override
    public List<LoanRecordDTO> findOpenLoansOfMember(String memberId) {
        // Danh sach ban sao
        List<LoanRecordDTO> resultList = new ArrayList<>();

        // Loc: dung thanh vien va chua tra
        for (Loan loan : loanMap.values()) {
            // Luot dang mo cua thanh vien nay
            if (loan.isOpen() && loan.getMemberId().equals(memberId)) {
                resultList.add(toRecord(loan));
            }
        }
        return resultList;
    }

    // Luot dang mo cua (thanh vien, tai lieu)
    @Override
    public LoanRecordDTO findOpenLoan(LoanRequestDTO loanRequestDTO)
            throws LoanNotFoundException {
        // Duyet tim luot dang mo khop ca hai ma
        for (Loan loan : loanMap.values()) {
            // Khop ca thanh vien, tai lieu va chua tra
            if (loan.isOpen() && loan.getMemberId().equals(loanRequestDTO.getMemberId())
                    && loan.getItemId().equals(loanRequestDTO.getItemId())) {
                return toRecord(loan);
            }
        }
        throw new LoanNotFoundException(String.format(Message.ERROR_LOAN_NOT_FOUND,
                loanRequestDTO.getMemberId(), loanRequestDTO.getItemId()));
    }

    // Ghi luot muon moi: chong muon trung, cap ma, ghi lai tep
    @Override
    public String addLoan(LoanRecordDTO loanRecordDTO)
            throws DuplicateKeyException, StorageException {
        // Khoa luot dang mo
        String openKey = toOpenKey(loanRecordDTO.getMemberId(), loanRecordDTO.getItemId());

        // Dang muon dung tai lieu nay roi
        if (openKeySet.contains(openKey)) {
            throw new DuplicateKeyException(String.format(Message.ERROR_ALREADY_BORROWING,
                    loanRecordDTO.getMemberId(), loanRecordDTO.getItemId()));
        }

        // Cap ma, dung model tu ban ghi
        lastNumber++;
        Loan loan = new Loan(String.format(Constants.LOAN_ID_FORMAT, lastNumber),
                loanRecordDTO.getMemberId(), loanRecordDTO.getItemId());
        loan.setBorrowDate(loanRecordDTO.getBorrowDate());
        loan.setDueDate(loanRecordDTO.getDueDate());
        loanMap.put(loan.getId(), loan);
        openKeySet.add(openKey);
        saveToFile();
        return loan.getId();
    }

    // Dong luot muon: ngay tra + tien phat, bo khoi tap dang mo, ghi lai tep
    @Override
    public void closeLoan(LoanRecordDTO loanRecordDTO)
            throws LoanNotFoundException, StorageException {
        // Luot can dong
        Loan loan = loanMap.get(loanRecordDTO.getId());

        // Khong co hoac da tra roi
        if ((loan == null) || (!loan.isOpen())) {
            throw new LoanNotFoundException(String.format(Message.ERROR_LOAN_NOT_FOUND,
                    loanRecordDTO.getMemberId(), loanRecordDTO.getItemId()));
        }
        loan.setReturnDate(loanRecordDTO.getReturnDate());
        loan.setFine(loanRecordDTO.getFine());
        openKeySet.remove(toOpenKey(loan.getMemberId(), loan.getItemId()));
        saveToFile();
    }

    // So luot muon
    @Override
    public int countLoans() {
        return loanMap.size();
    }

    // Cau bao luc nap (ban sao)
    @Override
    public List<String> findLoadErrorList() {
        return new ArrayList<>(loadErrorList);
    }

    // Khoa luot dang mo: "M001|B002"
    private String toOpenKey(String memberId, String itemId) {
        return memberId + Constants.KEY_SEPARATOR + itemId;
    }

    // Nap tep: moi dong mot khoi try
    private void loadFromFile() {
        // Doc moi dong; loi doc that thi ghi cau bao
        try {
            // Cac dong du lieu da tach
            List<CsvRowDTO> rowList = CsvUtils.readRows(filePath, loadErrorList);

            // Doi tung dong thanh model
            for (CsvRowDTO row : rowList) {
                // Dong hong: 1 cau bao kem so dong
                try {
                    loadRow(row);
                } catch (LibraryException e) {
                    // Bo qua dong nay
                    loadErrorList.add(String.format(Message.ERROR_CSV_LINE, filePath,
                            row.getLineNumber(), e.getMessage()));
                    isBackupNeeded = true;
                }
            }
        } catch (StorageException e) {
            // Khong doc duoc tep: kho rong
            loadErrorList.add(e.getMessage());
        }
    }

    // Doi 1 dong tep thanh model: kiem ma, ngay (dung lich, dung thu tu), tien phat
    private void loadRow(CsvRowDTO row) throws InvalidInputException, DuplicateKeyException {
        // Cac gia tri cua dong
        List<String> valueList = row.getValueList();

        // Dung so cot
        if (valueList.size() != Constants.LOAN_CSV_COLUMNS) {
            throw new InvalidInputException(String.format(Message.ERROR_CSV_COLUMNS,
                    Constants.LOAN_CSV_COLUMNS, valueList.size()));
        }

        // Ma luot: L + 4 chu so
        String id = valueList.get(Constants.LOAN_CSV_ID_INDEX).trim();
        if (!id.matches(Constants.REGEX_LOAN_ID)) {
            // Kiem ma luot truoc khi doc cac cot khac
            throw new InvalidInputException(String.format(Message.ERROR_LOAN_ID, id));
        }

        // Ma thanh vien, ma tai lieu, ngay muon, han tra qua bo kiem chung
        Loan loan = new Loan(id,
                Validation.getMemberId(valueList.get(Constants.LOAN_CSV_MEMBER_INDEX)),
                Validation.getItemId(valueList.get(Constants.LOAN_CSV_ITEM_INDEX)));
        loan.setBorrowDate(Validation.getFileDate(valueList.get(Constants.LOAN_CSV_BORROW_INDEX)));
        loan.setDueDate(Validation.getFileDate(valueList.get(Constants.LOAN_CSV_DUE_INDEX)));
        loan.setReturnDate(readReturnDate(valueList.get(Constants.LOAN_CSV_RETURN_INDEX)));
        loan.setFine(Validation.getNonNegative(valueList.get(Constants.LOAN_CSV_FINE_INDEX),
                Message.FIELD_FINE));
        checkLoadedLoan(loan);
        loanMap.put(id, loan);

        // Luot dang mo thi giu khoa chong muon trung
        if (loan.isOpen()) {
            openKeySet.add(toOpenKey(loan.getMemberId(), loan.getItemId()));
        }
        lastNumber = Math.max(lastNumber, Integer.parseInt(id.substring(
                Constants.ID_PREFIX_LENGTH)));
    }

    // O ngay tra: trong = chua tra (null), co chu thi phai la ngay hop le
    private LocalDate readReturnDate(String value) throws InvalidInputException {
        // O trong: luot dang mo
        if (value.trim().isEmpty()) {
            return null;
        }
        return Validation.getFileDate(value);
    }

    // Kiem luot vua nap: thu tu ngay hop ly, khong trung ma, khong 2 luot mo cung tai lieu
    private void checkLoadedLoan(Loan loan) throws InvalidInputException,
            DuplicateKeyException {
        // Han tra truoc ngay muon
        if (loan.getDueDate().isBefore(loan.getBorrowDate())) {
            throw new InvalidInputException(String.format(Message.ERROR_DUE_BEFORE_BORROW,
                    FormatUtils.formatDate(loan.getDueDate()),
                    FormatUtils.formatDate(loan.getBorrowDate())));
        }

        // Tra truoc ngay muon
        if ((!loan.isOpen()) && loan.getReturnDate().isBefore(loan.getBorrowDate())) {
            throw new InvalidInputException(String.format(Message.ERROR_RETURN_BEFORE_BORROW,
                    FormatUtils.formatDate(loan.getReturnDate()),
                    FormatUtils.formatDate(loan.getBorrowDate())));
        }

        // Hai dong cung ma luot
        if (loanMap.containsKey(loan.getId())) {
            throw new DuplicateKeyException(String.format(Message.ERROR_DUPLICATE_ID,
                    loan.getId()));
        }

        // Hai luot dang mo cung (thanh vien, tai lieu)
        if (loan.isOpen() && openKeySet.contains(toOpenKey(loan.getMemberId(),
                loan.getItemId()))) {
            throw new DuplicateKeyException(String.format(Message.ERROR_ALREADY_BORROWING,
                    loan.getMemberId(), loan.getItemId()));
        }
    }

    // Ghi lai ca tep
    private void saveToFile() throws StorageException {
        // Lan ghi dau sau khi nap thay dong hong: giu tep goc
        if (isBackupNeeded) {
            CsvUtils.backupFile(filePath);
            isBackupNeeded = false;
        }

        // Moi luot thanh 1 dong CSV (ngay ghi dang yyyy-MM-dd)
        List<String> lineList = new ArrayList<>();
        for (Loan loan : loanMap.values()) {
            // Gia tri cac cot theo dong tieu de
            List<String> valueList = new ArrayList<>();
            valueList.add(loan.getId());
            valueList.add(loan.getMemberId());
            valueList.add(loan.getItemId());
            valueList.add(FormatUtils.formatFileDate(loan.getBorrowDate()));
            valueList.add(FormatUtils.formatFileDate(loan.getDueDate()));
            valueList.add(FormatUtils.formatFileDate(loan.getReturnDate()));
            valueList.add(String.valueOf(loan.getFine()));
            lineList.add(CsvUtils.joinLine(valueList));
        }
        CsvUtils.writeRows(filePath, Constants.LOAN_CSV_HEADER, lineList);
    }

    // Model -> ban sao DTO
    private LoanRecordDTO toRecord(Loan loan) {
        // Dong ban sao
        LoanRecordDTO record = new LoanRecordDTO();
        record.setId(loan.getId());
        record.setMemberId(loan.getMemberId());
        record.setItemId(loan.getItemId());
        record.setBorrowDate(loan.getBorrowDate());
        record.setDueDate(loan.getDueDate());
        record.setReturnDate(loan.getReturnDate());
        record.setFine(loan.getFine());
        return record;
    }
}

