package service;

import dto.BookResponseDTO;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.List;

/**
 * Nghiep vu tai lieu: tim theo ten (khong phan biet hoa thuong), sap A-Z, danh so — tren
 * danh sach Controller dua vao. Khong giu kho.
 *
 * @author CuongThai Academy
 */
public class BookService {

    // Service khong giu du lieu
    public BookService() {
    }

    // Tai lieu co ten chua tu khoa; sap theo ten (cung ten thi theo ma), danh so tu 1
    public List<BookResponseDTO> searchByTitle(List<BookResponseDTO> itemList,
            String keyword) {
        // Tu khoa viet thuong de so khong phan biet hoa thuong
        String lowerKeyword = keyword.toLowerCase();
        List<BookResponseDTO> foundList = new ArrayList<>();

        // Loc theo ten
        for (BookResponseDTO item : itemList) {
            // Ten chua tu khoa
            if (item.getTitle().toLowerCase().contains(lowerKeyword)) {
                foundList.add(item);
            }
        }

        // Sap theo ten roi theo ma, danh so
        Collections.sort(foundList, Comparator.comparing(BookResponseDTO::getTitle,
                String.CASE_INSENSITIVE_ORDER).thenComparing(BookResponseDTO::getId));
        for (int i = 0; i < foundList.size(); i++) {
            // Danh so theo thu tu da sap
            foundList.get(i).setNo(i + 1);
        }
        return foundList;
    }
}

