 * (HashMap loai the -> IFeePolicy) va ngay lam viec. Trai luat thi NEM ngoai le nghiep vu;
 * Service khong bat, khong in — Controller bat, View in.
 * Thu tu kiem khi muon: the bi khoa -> qua han muc -> het ban (loi nao den truoc bao truoc).
 *
 * @author CuongThai Academy
 */
public class LoanService {

    // Chinh sach phi theo loai the
    private Map<Integer, IFeePolicy> feePolicyMap;

    // Ngay lam viec cua quay (ngay muon, ngay tra, moc tinh qua han)
    private LocalDate workingDate;

    // Tao service voi 2 chinh sach phi; ngay lam viec mac dinh la hom nay cua may
    public LoanService() {
        feePolicyMap = new HashMap<>();
        feePolicyMap.put(Constants.MEMBER_STUDENT, new StudentFeePolicy());
        feePolicyMap.put(Constants.MEMBER_STAFF, new StaffFeePolicy());
        workingDate = LocalDate.now();
    }

    // Tra ve ngay lam viec
    public LocalDate getWorkingDate() {
        return workingDate;
    }

    // Gan ngay lam viec
    public void setWorkingDate(LocalDate workingDate) {
        this.workingDate = workingDate;
    }

    // The bi khoa khi no phat LON HON muc khoa (bang muc van duoc muon)
    public boolean isLocked(MemberResponseDTO member) {
        return member.getDebt() > Constants.LOCK_DEBT_LIMIT;
    }

    // Kiem 3 luat roi lap luot muon moi (chua co ma — kho cap): ngay muon = ngay lam viec,
    // han tra = ngay muon + so ngay muon cua LOAI tai lieu (da hinh: 14 / 7 / 3)
    public LoanRecordDTO createLoan(MemberResponseDTO member, BookResponseDTO item)
            throws MemberLockedException, LoanLimitException, ItemNotAvailableException {
        // Luat 1: no phat qua muc thi khoa the
        if (isLocked(member)) {
            throw new MemberLockedException(String.format(Message.ERROR_MEMBER_LOCKED,
                    member.getId(), FormatUtils.formatMoney(member.getDebt()),
                    FormatUtils.formatMoney(Constants.LOCK_DEBT_LIMIT)));
        }

        // Luat 2: dang muon du so toi da cua loai the
        if (member.getOpenLoanCount() >= member.getMaxLoans()) {
            throw new LoanLimitException(String.format(Message.ERROR_LOAN_LIMIT, member.getId(),
                    member.getOpenLoanCount(), member.getMaxLoans(), member.getTypeName()));
        }

        // Luat 3: het ban tren ke
        if (item.getCopies() <= 0) {
            throw new ItemNotAvailableException(String.format(Message.ERROR_NO_COPY,
                    item.getId(), item.getTitle()));
        }

        // Du luat: lap luot muon
        LoanRecordDTO loan = new LoanRecordDTO();
        loan.setMemberId(member.getId());
        loan.setItemId(item.getId());
        loan.setItemTitle(item.getTitle());
        loan.setBorrowDate(workingDate);
        loan.setDueDate(workingDate.plusDays(item.getLoanDays()));
        return loan;
    }

    // Dong luot muon vao ngay lam viec: so ngay tre + tien phat theo chinh sach cua loai the.
    // lateFeePerDay cua tai lieu da duoc Controller dien vao openLoan
    public LoanRecordDTO closeLoan(LoanRecordDTO openLoan, MemberResponseDTO member)
            throws InvalidInputException {
        // TODO DA.1 — (1) ngay lam viec truoc ngay muon: nem InvalidInputException
        //   (Message.ERROR_RETURN_BEFORE_BORROW, ngay lam viec, ngay muon — dd/MM/yyyy).
        //   (2) returnDate = ngay lam viec; daysLate = countDaysLate(han tra, ngay lam viec).
        //   (3) fine = chinh sach cua LOAI THE (findPolicy) .calculateFee(daysLate,
        //   lateFeePerDay cua luot). Khong if theo loai the: hoi HashMap chinh sach.
        return openLoan;
    }

    // Phi UOC TINH neu luot dang mo duoc tra vao ngay lam viec (bao cao qua han)
    public int estimateFine(LoanRecordDTO openLoan, int memberType) {
        return findPolicy(memberType).calculateFee(countDaysLate(openLoan.getDueDate(),
                workingDate), openLoan.getLateFeePerDay());
    }

    // So ngay tre: tra sau han bao nhieu ngay (dung han hoac som thi 0)
    public int countDaysLate(LocalDate dueDate, LocalDate endDate) {
        return Math.max(0, FormatUtils.daysBetween(dueDate, endDate));
    }

    // Ten chinh sach phi cua loai the (in kem ket qua tra)
    public String findPolicyName(int memberType) {
        return findPolicy(memberType).getPolicyName();
    }

    // No moi sau khi cong tien phat cua lan tra
    public int addFine(MemberResponseDTO member, int fine) {
        return member.getDebt() + fine;
    }

    // No moi sau khi nop tien: khong no thi khong thu, nop qua no thi tu choi (khong tra lai)
    public int payFine(MemberResponseDTO member, int amount) throws InvalidInputException {
        // TODO DA.2 — no 0d: nem InvalidInputException(Message.ERROR_NO_DEBT); nop nhieu hon
        //   no: nem InvalidInputException(Message.ERROR_PAY_TOO_MUCH, so nop, so no — formatMoney);
        //   con lai tra ve no moi = no - so nop.
        return member.getDebt();
    }

    // Chuan bi cac luot dang mo de in the thanh vien: so ngay tre tinh den ngay lam viec,
    // sap theo han tra (som nhat truoc), danh so tu 1
    public List<LoanRecordDTO> prepareOpenLoans(List<LoanRecordDTO> openLoanList) {
        // Ban sao danh sach de sap (khong doi danh sach cua noi goi)
        List<LoanRecordDTO> resultList = new ArrayList<>(openLoanList);

        // Han tra som truoc; cung han thi theo ma luot
        Collections.sort(resultList, Comparator.comparing(LoanRecordDTO::getDueDate)
                .thenComparing(LoanRecordDTO::getId));

        // Danh so va tinh so ngay tre
        for (int i = 0; i < resultList.size(); i++) {
            resultList.get(i).setNo(i + 1);
            resultList.get(i).setDaysLate(countDaysLate(resultList.get(i).getDueDate(),
                    workingDate));
        }
        return resultList;
    }

    // Chinh sach cua loai the (loai la thi dung chinh sach sinh vien — khong bao gio null)
    private IFeePolicy findPolicy(int memberType) {
        // Chinh sach theo loai the
        IFeePolicy policy = feePolicyMap.get(memberType);

        // Loai the chua co chinh sach rieng
        if (policy == null) {
            return feePolicyMap.get(Constants.MEMBER_STUDENT);
        }
        return policy;
    }
}

