package service;

import constants.Constants;
import constants.Message;

/**
 * Chinh sach phi tre cho can bo: mien phi 2 ngay tre dau tien, tu ngay thu 3 tinh du.
 *
 * @author CuongThai Academy
 */
public class StaffFeePolicy implements IFeePolicy {

    // Chinh sach khong giu du lieu nao
    public StaffFeePolicy() {
    }

    // Ten chinh sach, kem so ngay duoc mien lay tu Constants
    @Override
    public String getPolicyName() {
        return String.format(Message.POLICY_STAFF, Constants.STAFF_FREE_DAYS);
    }

    // Bo di STAFF_FREE_DAYS ngay tre dau (khong am), phan con lai tinh du phi
    @Override
    public int calculateFee(int daysLate, int lateFeePerDay) {
        // So ngay tre con phai tra tien
        int chargedDays = Math.max(0, daysLate - Constants.STAFF_FREE_DAYS);

        return chargedDays * lateFeePerDay;
    }
}

package service;

import constants.Constants;
import constants.Message;

/**
 * Chinh sach phi tre cho sinh vien: tinh du ngay tre, roi giam 50%.
 *
 * @author CuongThai Academy
 */
public class StudentFeePolicy implements IFeePolicy {

    // Chinh sach khong giu du lieu nao
    public StudentFeePolicy() {
    }

    // Ten chinh sach, kem phan tram giam lay tu Constants
    @Override
    public String getPolicyName() {
        return String.format(Message.POLICY_STUDENT, Constants.STUDENT_DISCOUNT_PERCENT);
    }

    // Phi day du (ngay tre x phi/ngay) nhan phan tram con phai tra (100 - 50)
    @Override
    public int calculateFee(int daysLate, int lateFeePerDay) {
        // Phi khi chua giam
        int fullFee = daysLate * lateFeePerDay;

        return fullFee * (Constants.PERCENT_FULL - Constants.STUDENT_DISCOUNT_PERCENT)
                / Constants.PERCENT_FULL;
    }
}

package utils;

import constants.Constants;
import constants.Message;
import dto.CsvRowDTO;
import exceptions.InvalidInputException;
import exceptions.StorageException;
import java.io.BufferedReader;
import java.io.File;
import java.io.FileInputStream;
import java.io.FileOutputStream;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.OutputStreamWriter;
import java.io.PrintWriter;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.StandardCopyOption;
import java.util.ArrayList;
import java.util.List;

/**
 * Doc/ghi TEP CSV dung chung cho ca 3 kho (sach, thanh vien, luot muon) — "FileRepository"
 * viet MOT lan: (1) doc tung dong bang ma UTF-8 (bo BOM, bo dong tieu de, bo dong trong), tach
 * dong co ngoac kep, tra ve dong + SO DONG de bao loi dung cho; (2) ghi qua TEP TAM roi moi
 * thay tep that (mat dien giua chung thi tep cu van nguyen); (3) sao luu .bak truoc lan ghi
 * dau sau khi nap thay dong hong. Kho nao cung chi con viec doi 1 dong <-> 1 model.
 * Ham static, khong giu du lieu.
 *
 * @author CuongThai Academy
 */
public final class CsvUtils {

    // Ngan khong cho tao doi tuong CsvUtils (chi co ham static)
    private CsvUtils() {
    }

    // Doc ca tep: moi dong du lieu thanh 1 CsvRowDTO (so dong + gia tri). Tep chua co thi
    // ghi cau bao vao errorList va tra danh sach rong; dong ngoac kep hong cung la 1 cau bao.
    // Loi doc that (IOException) thi nem StorageException kem ten tep.
    public static List<CsvRowDTO> readRows(String filePath, List<String> errorList)
            throws StorageException {
        // Cac dong da doc, tep can doc
        List<CsvRowDTO> rowList = new ArrayList<>();
        File file = new File(filePath);

        // Lan chay dau tien: chua co tep thi kho rong, khong phai loi
        if (!file.exists()) {
            errorList.add(String.format(Message.FILE_NOT_FOUND, filePath));
            return rowList;
        }

        // Mo bang try-with-resources: luon duoc dong, ke ca khi nem loi giua chung
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(
                new FileInputStream(file), StandardCharsets.UTF_8))) {
            // Dong vua doc va so dong (dem tu 1)
            String line = reader.readLine();
            int lineNumber = 0;

            // readLine tra null = het tep
            while (line != null) {
                lineNumber++;
                // Dong 1: bo BOM (Excel hay them) truoc khi so voi dong tieu de
                if (lineNumber == Constants.CSV_HEADER_LINE) {
                    line = line.replace(Constants.BOM, Constants.EMPTY);
                }
                // Dong tieu de va dong trong thi bo qua, khong bao
                if ((lineNumber != Constants.CSV_HEADER_LINE) && (!line.trim().isEmpty())) {
                    // Tach dong; ngoac kep hong thi chi la 1 cau bao, cac dong sau doc tiep
                    try {
                        CsvRowDTO row = new CsvRowDTO();
                        row.setLineNumber(lineNumber);
                        row.setValueList(splitLine(line));
                        rowList.add(row);
                    } catch (InvalidInputException e) {
                        // Mot dong hong khong lam hong ca tep
                        errorList.add(String.format(Message.ERROR_CSV_LINE, filePath, lineNumber,
                                e.getMessage()));
                    }
                }
                line = reader.readLine();
            }
        } catch (IOException e) {
            // Loi doc that: boc thanh loi luu tru, giu e lam nguyen nhan goc
            throw new StorageException(String.format(Message.ERROR_FILE_READ, filePath,
                    e.getMessage()), e);
        }

        return rowList;
    }

    // Ghi ca tep: dong tieu de + moi dong du lieu (da la chuoi CSV), qua tep .tmp roi
    // Files.move de thay tep that. Bat ky buoc nao hong thi nem StorageException.
    public static void writeRows(String filePath, String header, List<String> lineList)
            throws StorageException {
        // Tep that, tep tam ben canh no
        File file = new File(filePath);
        File tempFile = new File(filePath + Constants.TEMP_SUFFIX);

        // Thu muc cha chua co (vd data/) thi tao
        if ((file.getParentFile() != null) && (!file.getParentFile().exists())) {
            file.getParentFile().mkdirs();
        }

        // Ghi tep tam bang UTF-8 (GOI TEN bang ma, khong dung mac dinh cua may)
        try (PrintWriter writer = new PrintWriter(new OutputStreamWriter(
                new FileOutputStream(tempFile), StandardCharsets.UTF_8))) {
            writer.println(header);
            // Moi dong du lieu mot dong tep
            for (String line : lineList) {
                writer.println(line);
            }
            // PrintWriter KHONG nem IOException: phai tu hoi no co loi khong
            if (writer.checkError()) {
                throw new StorageException(String.format(Message.ERROR_FILE_WRITE, filePath,
                        Message.WRITER_ERROR), null);
            }
        } catch (IOException e) {
            // Khong mo duoc tep tam (thu muc khong co quyen ghi...)
            throw new StorageException(String.format(Message.ERROR_FILE_WRITE, filePath,
                    e.getMessage()), e);
        }

        // Tep tam da du: thay tep that bang 1 buoc doi ten
        try {
            Files.move(tempFile.toPath(), file.toPath(), StandardCopyOption.REPLACE_EXISTING);
        } catch (IOException e) {
            // Doi ten that bai: tep cu van nguyen, bao loi
            throw new StorageException(String.format(Message.ERROR_FILE_WRITE, filePath,
                    e.getMessage()), e);
        }
    }

    // Sao luu tep goc thanh <tep>.bak (giu dong hong de nguoi dung sua tay sau)
    public static void backupFile(String filePath) throws StorageException {
        // Tep goc
        File file = new File(filePath);

        // Chua co tep thi khong co gi de sao luu
        if (!file.exists()) {
            return;
        }

        // Chep de len ban .bak cu
        try {
            Files.copy(file.toPath(), new File(filePath + Constants.BACKUP_SUFFIX).toPath(),
                    StandardCopyOption.REPLACE_EXISTING);
        } catch (IOException e) {
            // Khong chep duoc: bao loi, khong ghi de tep goc
            throw new StorageException(String.format(Message.ERROR_FILE_WRITE,
                    filePath + Constants.BACKUP_SUFFIX, e.getMessage()), e);
        }
    }

    // Noi cac gia tri thanh 1 dong CSV (gia tri can thi boc ngoac kep)
    public static String joinLine(List<String> valueList) {
        // Dong dang gom (khong dung String +=)
        StringBuilder lineBuilder = new StringBuilder();

        // Gia tri thu 2 tro di thi them dau phay phia truoc
        for (String value : valueList) {
            // Khong phai gia tri dau tien: them dau ngan
            if (lineBuilder.length() > 0) {
                lineBuilder.append(Constants.CSV_SEPARATOR);
            }
            lineBuilder.append(toCsvValue(value));
        }

        return lineBuilder.toString();
    }

    // Tach 1 dong CSV thanh cac gia tri; dau phay NAM TRONG ngoac kep la chu, khong phai dau
    // ngan. Ngoac kep mo ma khong dong thi dong hong: nem InvalidInputException
    public static List<String> splitLine(String line) throws InvalidInputException {
        // Cac gia tri da tach, gia tri dang gom, dang o trong ngoac kep hay khong, vi tri doc
        List<String> valueList = new ArrayList<>();
        StringBuilder valueBuilder = new StringBuilder();
        boolean isInQuotes = false;
        int index = 0;

        // Doc tung ky tu tu trai sang phai
        while (index < line.length()) {
            // Ky tu dang doc
            char character = line.charAt(index);

            // Trong ngoac kep: "" la 1 dau ngoac kep that, " don le la dong ngoac
            if (isInQuotes) {
                // Gap dau ngoac kep: xem ky tu ke tiep
                if (character == Constants.CSV_QUOTE_CHAR) {
                    // Ngoac kep doi: giu 1 dau, nhay qua dau thu hai
                    if ((index + 1 < line.length())
                            && (line.charAt(index + 1) == Constants.CSV_QUOTE_CHAR)) {
                        valueBuilder.append(character);
                        index++;
                    } else {
                        // Ngoac kep don: het phan trong ngoac
                        isInQuotes = false;
                    }
                } else {
                    // Moi ky tu khac trong ngoac (ke ca dau phay) la chu cua gia tri
                    valueBuilder.append(character);
                }
            } else if (character == Constants.CSV_QUOTE_CHAR) {
                // Ngoai ngoac kep gap dau ngoac kep: mo phan trong ngoac
                isInQuotes = true;
            } else if (character == Constants.CSV_SEPARATOR_CHAR) {
                // Dau phay ngoai ngoac: het 1 gia tri, bat dau gia tri moi
                valueList.add(valueBuilder.toString());
                valueBuilder.setLength(0);
            } else {
                // Ky tu thuong
                valueBuilder.append(character);
            }
            index++;
        }

        // Het dong ma ngoac kep chua dong: dong hong
        if (isInQuotes) {
            throw new InvalidInputException(Message.ERROR_CSV_QUOTE);
        }

        // Gia tri cuoi cung (sau dau phay cuoi)
        valueList.add(valueBuilder.toString());
        return valueList;
    }

    // Doi 1 gia tri thanh dang ghi duoc vao CSV: co dau phay hoac ngoac kep thi nhan doi moi
    // ngoac kep roi boc ca gia tri trong ngoac kep; khong co thi giu nguyen
    public static String toCsvValue(String value) {
        // Gia tri thuong (khong dau phay, khong ngoac kep) ghi nguyen
        if ((!value.contains(Constants.CSV_SEPARATOR)) && (!value.contains(Constants.CSV_QUOTE))) {
            return value;
        }

        // Nhan doi ngoac kep ben trong, roi boc ca gia tri
        return Constants.CSV_QUOTE + value.replace(Constants.CSV_QUOTE,
                Constants.CSV_QUOTE + Constants.CSV_QUOTE) + Constants.CSV_QUOTE;
    }
}

package utils;

import constants.Constants;
import java.time.LocalDate;
import java.time.format.DateTimeFormatter;
import java.time.temporal.ChronoUnit;

/**
 * Dinh dang so lieu de IN ra va de GHI tep: tien kieu Viet Nam (65.000d), ngay dd/MM/yyyy
 * (man hinh) va yyyy-MM-dd (tep), thang MM/yyyy, cat ten dai cho vua cot bang, dem ngay.
 * Ham static, khong giu du lieu.
 *
 * @author CuongThai Academy
 */
public final class FormatUtils {

    // Ngan khong cho tao doi tuong FormatUtils (chi co ham static)
    private FormatUtils() {
    }

    // Tien kieu Viet Nam: dau cham ngan nghin + chu d (65000 -> 65.000d) — giong nhau moi may
    public static String formatMoney(int amount) {
        // %,d dung dau phay theo Locale cua may; doi ve dau cham cho chac
        return String.format(Constants.MONEY_FORMAT, amount)
                .replace(Constants.COMMA, Constants.THOUSAND_SEPARATOR) + Constants.CURRENCY;
    }

    // Ngay de in: dd/MM/yyyy; null (chua tra) thi in dau gach
    public static String formatDate(LocalDate date) {
        // Chua co ngay thi in ky hieu "chua co"
        if (date == null) {
            return Constants.NO_DATE;
        }
        return date.format(DateTimeFormatter.ofPattern(Constants.DATE_PATTERN));
    }

    // Ngay de ghi tep: yyyy-MM-dd; null thi ghi chuoi rong
    public static String formatFileDate(LocalDate date) {
        // Chua co ngay thi o trong
        if (date == null) {
            return Constants.EMPTY;
        }
        return date.format(DateTimeFormatter.ofPattern(Constants.FILE_DATE_PATTERN));
    }

    // Thang cua mot ngay: MM/yyyy (khoa nhom bao cao doanh thu)
    public static String formatMonth(LocalDate date) {
        return date.format(DateTimeFormatter.ofPattern(Constants.MONTH_PATTERN));
    }

    // Cat chuoi dai hon maxLength, them dau ... (bang in khong bi lech cot)
    public static String cut(String text, int maxLength) {
        // Vua cot thi giu nguyen
        if (text.length() <= maxLength) {
            return text;
        }
        return text.substring(0, maxLength - Constants.ELLIPSIS.length()) + Constants.ELLIPSIS;
    }

    // So ngay tu ngay a toi ngay b (b truoc a thi am)
    public static int daysBetween(LocalDate from, LocalDate to) {
        return (int) ChronoUnit.DAYS.between(from, to);
    }
}

package utils;

import constants.Constants;
import constants.Message;
import exceptions.InvalidInputException;
import java.time.LocalDate;
import java.time.format.DateTimeFormatter;
import java.time.format.DateTimeParseException;
import java.time.format.ResolverStyle;

/**
 * Kiem va lam sach chu nguoi dung go (va gia tri doc tu tep CSV): nhan chuoi, tra ve gia tri
 * sach hoac nem InvalidInputException kem cau bao loi noi ro sai o dau. Khong doc ban phim.
 * Kho tren tep DUNG LAI dung cac ham nay khi nap tung dong: mot luat, hai cua vao.
 *
 * @author CuongThai Academy
 */
public final class Validation {

    // Ngan khong cho tao doi tuong Validation (chi co ham static)
    private Validation() {
    }

    // Doi chu thanh so nguyen va kiem so nam trong [min, max]
    public static int getChoice(String input, int min, int max) throws InvalidInputException {
        // Lua chon sau khi doi
        int choice = 0;

        // Thu doi chu sang so nguyen (bo dau cach 2 dau truoc)
        try {
            choice = Integer.parseInt(input.trim());
        } catch (NumberFormatException e) {
            // Go chu, so thuc hoac de trong: doi sang loi nhap, giu e lam nguyen nhan goc
            throw new InvalidInputException(Message.ERROR_NOT_INTEGER, e);
        }

        // Ngoai khoang thi bao khoang dung
        if ((choice < min) || (choice > max)) {
            throw new InvalidInputException(String.format(Message.ERROR_CHOICE_RANGE, min, max));
        }

        return choice;
    }

    // Chuan hoa ten tai lieu: bo dau cach thua, moi tu viet hoa chu dau (Title Case)
    public static String getTitle(String input) throws InvalidInputException {
        // Ten da chuan hoa
        String title = toTitleCase(input);

        // Rong (hoac chi co dau cach) thi bao loi
        if (title.isEmpty()) {
            throw new InvalidInputException(Message.ERROR_TITLE_EMPTY);
        }

        // Ten da chuan hoa dai qua gioi han thi bao do dai
        if (title.length() > Constants.TITLE_MAX_LENGTH) {
            throw new InvalidInputException(
                    String.format(Message.ERROR_TITLE_LENGTH, title.length(),
                    Constants.TITLE_MAX_LENGTH));
        }

        return title;
    }

    // Kiem va chuan hoa ten tac gia
    public static String getAuthor(String input) throws InvalidInputException {
        return getPersonName(input, Message.FIELD_AUTHOR);
    }

    // Kiem va chuan hoa ho ten thanh vien
    public static String getMemberName(String input) throws InvalidInputException {
        return getPersonName(input, Message.FIELD_MEMBER_NAME);
    }

    // Doi chu thanh so ban va kiem trong [COPIES_MIN, COPIES_MAX]
    public static int getCopies(String input) throws InvalidInputException {
        // So ban sau khi doi
        int copies = parseInteger(input, Message.FIELD_COPIES);

        // Ngoai khoang thi bao khoang dung va so da nhap
        if ((copies < Constants.COPIES_MIN) || (copies > Constants.COPIES_MAX)) {
            throw new InvalidInputException(
                    String.format(Message.ERROR_NUMBER_RANGE, Message.FIELD_COPIES,
                    Constants.COPIES_MIN, Constants.COPIES_MAX, copies));
        }

        return copies;
    }

    // Kiem ma tai lieu: B, T hoac D + 3 chu so, nhan ca chu thuong (d006 -> D006)
    public static String getItemId(String input) throws InvalidInputException {
        // Ma da bo dau cach 2 dau va viet hoa
        String itemId = input.trim().toUpperCase();

        // Sai dang thi bao lai dung chu nguoi dung go
        if (!itemId.matches(Constants.REGEX_ITEM_ID)) {
            throw new InvalidInputException(
                    String.format(Message.ERROR_ITEM_ID_FORMAT, input.trim()));
        }

        return itemId;
    }

    // Kiem ma thanh vien: M + 3 chu so, nhan ca chu thuong (m002 -> M002)
    public static String getMemberId(String input) throws InvalidInputException {
        // Ma da bo dau cach 2 dau va viet hoa
        String memberId = input.trim().toUpperCase();

        // Sai dang thi bao lai dung chu nguoi dung go
        if (!memberId.matches(Constants.REGEX_MEMBER_ID)) {
            throw new InvalidInputException(String.format(Message.ERROR_MEMBER_ID_FORMAT,
                    input.trim()));
        }

        return memberId;
    }

    // Doi chu thanh loai tai lieu: 1 sach, 2 tap chi, 3 DVD
    public static int getItemType(String input) throws InvalidInputException {
        return getChoice(input, Constants.TYPE_BOOK, Constants.TYPE_DVD);
    }

    // Kiem email co ban: co phan truoc @, co ten mien co dau cham sau @
    public static String getEmail(String input) throws InvalidInputException {
        // Email bo dau cach 2 dau, viet thuong
        String email = input.trim().toLowerCase();

        // Sai dang thi bao lai dung chu nguoi dung go
        if (!email.matches(Constants.REGEX_EMAIL)) {
            throw new InvalidInputException(String.format(Message.ERROR_EMAIL, input.trim()));
        }

        return email;
    }

    // Kiem ISBN-13: bo dau - va dau cach, du 13 chu so, dau 978/979, dung chu so kiem tra
    public static String getIsbn(String input) throws InvalidInputException {
        // Ban go, cac chu so gom duoc, tien to, tong co trong so, chu so kiem tra, chu so cuoi
        String text = input.trim();
        StringBuilder digitBuilder = new StringBuilder();
        String prefix = "";
        int weightedSum = 0;
        int checkDigit = 0;
        int lastDigit = 0;

        // Duyet tung ky tu: chu so thi giu, dau - / dau cach thi bo, con lai la loi
        for (int i = 0; i < text.length(); i++) {
            // Ky tu dang xet
            char character = text.charAt(i);

            // Chu so thi giu lai
            if (Constants.DIGITS.indexOf(character) >= 0) {
                digitBuilder.append(character);
            } else if (Constants.ISBN_SEPARATORS.indexOf(character) < 0) {
                // Khong phai chu so cung khong phai dau ngan cach: chi ro ky tu va vi tri
                throw new InvalidInputException(
                        String.format(Message.ERROR_ISBN_CHARACTER, character, i + 1));
            }
        }

        // Thieu hoac thua chu so thi bao so chu so dang co
        if (digitBuilder.length() != Constants.ISBN_LENGTH) {
            throw new InvalidInputException(
                    String.format(Message.ERROR_ISBN_LENGTH, Constants.ISBN_LENGTH,
                    digitBuilder.length()));
        }

        // Lay 3 chu so dau
        prefix = digitBuilder.substring(0, Constants.ISBN_PREFIX_LENGTH);

        // Ba chu so dau phai la 978 hoac 979
        if ((!prefix.equals(Constants.ISBN_PREFIX_978)) &&
                (!prefix.equals(Constants.ISBN_PREFIX_979))) {
            throw new InvalidInputException(String.format(Message.ERROR_ISBN_PREFIX, prefix));
        }

        // Cong 12 chu so dau: vi tri chan nhan 1, vi tri le nhan 3
        for (int i = 0; i < (Constants.ISBN_LENGTH - 1); i++) {
            // Gia tri cua chu so thu i
            int digit = Constants.DIGITS.indexOf(digitBuilder.charAt(i));

            // Vi tri le (1, 3, 5...) nhan 3, vi tri chan nhan 1
            if ((i % 2) == 1) {
                weightedSum = weightedSum + (digit * Constants.ISBN_ODD_WEIGHT);
            } else {
                // Vi tri chan giu nguyen
                weightedSum = weightedSum + digit;
            }
        }

        // Chu so kiem tra = (10 - tong % 10) % 10
        checkDigit = (Constants.ISBN_MODULO - (weightedSum % Constants.ISBN_MODULO))
                % Constants.ISBN_MODULO;

        // Gia tri chu so cuoi (chu so thu 13)
        lastDigit = Constants.DIGITS.indexOf(digitBuilder.charAt(Constants.ISBN_LENGTH - 1));

        // Chu so cuoi khac chu so tinh ra thi bao ca hai
        if (lastDigit != checkDigit) {
            throw new InvalidInputException(
                    String.format(Message.ERROR_ISBN_CHECKSUM, checkDigit, lastDigit));
        }

        return digitBuilder.toString();
    }

    // Kiem tu khoa tim kiem: bo dau cach 2 dau, khong duoc rong
    public static String getKeyword(String input) throws InvalidInputException {
        // Tu khoa bo dau cach 2 dau
        String keyword = input.trim();

        // Rong thi bao loi
        if (keyword.isEmpty()) {
            throw new InvalidInputException(Message.ERROR_KEYWORD_EMPTY);
        }

        return keyword;
    }

    // Doi chu thanh nam xuat ban: tu YEAR_MIN, khong lon hon nam hien tai cua may
    public static int getYear(String input) throws InvalidInputException {
        // Nam sau khi doi va nam hien tai (lay luc chay, khong viet cung)
        int year = parseInteger(input, Message.FIELD_YEAR);
        int currentYear = LocalDate.now().getYear();

        // O tuong lai thi bao rieng (khong in nam hien tai de output on dinh)
        if (year > currentYear) {
            throw new InvalidInputException(String.format(Message.ERROR_YEAR_FUTURE, year));
        }

        // Truoc YEAR_MIN thi bao nam nho nhat va so da nhap
        if (year < Constants.YEAR_MIN) {
            throw new InvalidInputException(
                    String.format(Message.ERROR_YEAR_MIN, Constants.YEAR_MIN, year));
        }

        return year;
    }

    // Doi chu thanh ky so tap chi trong [ISSUE_MIN, ISSUE_MAX]
    public static int getIssueNumber(String input) throws InvalidInputException {
        return getRange(input, Message.FIELD_ISSUE, Constants.ISSUE_RANGE_ARRAY);
    }

    // Doi chu thanh so phut DVD trong [MINUTES_MIN, MINUTES_MAX]
    public static int getMinutes(String input) throws InvalidInputException {
        return getRange(input, Message.FIELD_MINUTES, Constants.MINUTES_RANGE_ARRAY);
    }

    // Doi chu thanh loai the: 1 sinh vien, 2 can bo
    public static int getMemberType(String input) throws InvalidInputException {
        return getChoice(input, Constants.MEMBER_STUDENT, Constants.MEMBER_STAFF);
    }

    // Doi chu thanh so tien nop (dong): bo dau cham ngan nghin (65.000 -> 65000), phai > 0
    public static int getAmount(String input) throws InvalidInputException {
        // So tien sau khi bo dau cham ngan nghin
        int amount = parseInteger(input.replace(Constants.THOUSAND_SEPARATOR, Constants.EMPTY),
                Message.FIELD_AMOUNT);

        // Khong duong hoac qua tran thi bao khoang dung
        if ((amount <= 0) || (amount > Constants.AMOUNT_MAX)) {
            throw new InvalidInputException(String.format(Message.ERROR_AMOUNT_RANGE,
                    FormatUtils.formatMoney(Constants.AMOUNT_MAX)));
        }

        return amount;
    }

    // Doi chu dd/MM/yyyy (ban phim) thanh ngay; KIEM CHAT (31/02/2026 la loi, khong tu lui)
    public static LocalDate getDate(String input) throws InvalidInputException {
        return parseDate(input, Constants.DATE_PATTERN, Message.DATE_HINT);
    }

    // Doi chu yyyy-MM-dd (cot ngay trong tep CSV) thanh ngay, kiem chat nhu tren
    public static LocalDate getFileDate(String input) throws InvalidInputException {
        return parseDate(input, Constants.FILE_DATE_PATTERN, Message.FILE_DATE_HINT);
    }

    // Doi chu thanh so nguyen KHONG AM (cot no phat, tien phat trong tep CSV)
    public static int getNonNegative(String input, String fieldName)
            throws InvalidInputException {
        // So sau khi doi
        int number = parseInteger(input, fieldName);

        // Am thi bao loi kem ten cot
        if (number < 0) {
            throw new InvalidInputException(String.format(Message.ERROR_NEGATIVE, fieldName,
                    number));
        }

        return number;
    }

    // Doi chu theo mau ngay; mau "uuuu" + STRICT de 30/02 la loi, khong tu doi thanh 28/02
    private static LocalDate parseDate(String input, String pattern, String hint)
            throws InvalidInputException {
        // Bo doc ngay kiem chat
        DateTimeFormatter formatter = DateTimeFormatter.ofPattern(pattern)
                .withResolverStyle(ResolverStyle.STRICT);

        // Thu doi; sai dang hoac ngay khong co that thi bao kem dung chu da go
        try {
            return LocalDate.parse(input.trim(), formatter);
        } catch (DateTimeParseException e) {
            // Doi sang loi nhap, giu e lam nguyen nhan goc
            throw new InvalidInputException(String.format(Message.ERROR_DATE, input.trim(),
                    hint), e);
        }
    }

    // Doi chu thanh so nguyen va kiem trong khoang {min, max} cua mang hang
    private static int getRange(String input, String fieldName, int[] rangeArray)
            throws InvalidInputException {
        // So sau khi doi
        int number = parseInteger(input, fieldName);

        // Ngoai khoang thi bao khoang dung va so da nhap
        if ((number < rangeArray[0]) || (number > rangeArray[1])) {
            throw new InvalidInputException(String.format(Message.ERROR_NUMBER_RANGE, fieldName,
                    rangeArray[0], rangeArray[1], number));
        }

        return number;
    }

    // Kiem ten nguoi (chi chu cai khong dau + dau cach) roi chuan hoa Title Case
    private static String getPersonName(String input, String fieldName)
            throws InvalidInputException {
        // Ten da chuan hoa
        String name = toTitleCase(input);

        // Rong hoac co ky tu khac chu cai / dau cach thi bao loi kem ten o nhap
        if (!name.matches(Constants.REGEX_PERSON_NAME)) {
            throw new InvalidInputException(String.format(Message.ERROR_PERSON_NAME, fieldName));
        }

        return name;
    }

    // Doi chu thanh so nguyen; go chu thi bao loi kem ten o nhap
    private static int parseInteger(String input, String fieldName) throws InvalidInputException {
        // Thu doi chu sang so nguyen (bo dau cach 2 dau truoc)
        try {
            return Integer.parseInt(input.trim());
        } catch (NumberFormatException e) {
            // Go chu, so thuc hoac de trong: doi sang loi nhap, giu e lam nguyen nhan goc
            throw new InvalidInputException(String.format(Message.ERROR_NUMBER_FORMAT, fieldName),
                    e);
        }
    }

    // Bo dau cach thua, moi tu viet hoa chu dau (chuoi rong thi tra chuoi rong)
    private static String toTitleCase(String input) {
        // Chu bo dau cach 2 dau; bo noi cac tu da chuan hoa (khong dung String +=)
        String text = input.trim();
        StringBuilder resultBuilder = new StringBuilder();

        // Rong thi tra luon chuoi rong (noi goi tu bao loi)
        if (text.isEmpty()) {
            return text;
        }

        // Tach theo 1 hay nhieu dau cach, chuan hoa tung tu
        for (String word : text.split(Constants.REGEX_SPACES)) {
            // Tu thu 2 tro di thi them 1 dau cach phia truoc
            if (resultBuilder.length() > 0) {
                resultBuilder.append(Constants.SPACE);
            }

            // Chu dau viet hoa, phan con lai viet thuong
            resultBuilder.append(word.substring(0, 1).toUpperCase());
            resultBuilder.append(word.substring(1).toLowerCase());
        }

        return resultBuilder.toString();
    }
}

package view;

import constants.Constants;
import constants.Message;
import dto.BookResponseDTO;
import java.util.List;
import utils.FormatUtils;

/**
 * Man hinh tai lieu: in cau ket qua va bang tai lieu. Chi in, khong tinh gi.
 *
 * @author CuongThai Academy
 */
public class BookView {

    // View khong giu du lieu
    public BookView() {
    }

    // In mot cau ket qua (thanh cong hoac cau bao loi)
    public void showMessage(String message) {
        System.out.println(message);
    }

    // In bang tai lieu: dong tieu de roi moi tai lieu mot dong
    public void showItemList(List<BookResponseDTO> itemList) {
        System.out.println(Message.ITEM_TABLE_HEADER);

        // Moi tai lieu mot dong; ten dai thi cat cho vua cot
        for (BookResponseDTO item : itemList) {
            System.out.println(String.format(Constants.ITEM_ROW_FORMAT, item.getNo(),
                    item.getId(), item.getTypeName(),
