}

package view;

import constants.Constants;
import constants.Message;
import dto.LoanRecordDTO;
import dto.MemberResponseDTO;
import java.util.List;
import utils.FormatUtils;

/**
 * Man hinh muon - tra - no: cau ket qua va THE THANH VIEN (thong tin, no phat, trang thai
 * the, cac luot dang mo kem so ngay tre). Chi in.
 *
 * @author CuongThai Academy
 */
public class LoanView {

    // View khong giu du lieu
    public LoanView() {
    }

    // In mot cau ket qua
    public void showMessage(String message) {
        System.out.println(message);
    }

    // In the thanh vien + bang luot dang mo
    public void showMemberCard(MemberResponseDTO member, List<LoanRecordDTO> openLoanList) {
        System.out.println(Message.TITLE_MEMBER_CARD);
        System.out.println(String.format(Message.MEMBER_LINE, member.getId(),
                member.getTypeName(), member.getName(), member.getEmail()));

        // Trang thai the theo co locked ma Controller da dien (View khong tu tinh luat)
        String status = Message.STATUS_ACTIVE;
        if (member.isLocked()) {
            // Co khoa thi ghi kem muc khoa
            status = String.format(Message.STATUS_LOCKED,
                    FormatUtils.formatMoney(Constants.LOCK_DEBT_LIMIT));
        }
        System.out.println(String.format(Message.MEMBER_STATUS_LINE, member.getOpenLoanCount(),
                member.getMaxLoans(), FormatUtils.formatMoney(member.getDebt()), status));

        // Khong dang muon gi thi chi in 1 cau
        if (openLoanList.isEmpty()) {
            System.out.println(Message.NO_OPEN_LOAN);
            return;
        }
        System.out.println(Message.OPEN_LOAN_HEADER);

        // Moi luot dang mo mot dong
        for (LoanRecordDTO loan : openLoanList) {
            System.out.println(String.format(Constants.OPEN_LOAN_ROW_FORMAT, loan.getNo(),
                    loan.getId(), loan.getItemId(),
                    FormatUtils.cut(loan.getItemTitle(), Constants.TITLE_COLUMN),
                    FormatUtils.formatDate(loan.getDueDate()), loan.getDaysLate()));
        }
    }
}

package view;

import constants.Constants;
import constants.Message;
import dto.LoadReportDTO;
import dto.OverdueRowDTO;
import dto.RevenueRowDTO;
import dto.TopItemDTO;
import java.time.LocalDate;
import java.util.List;
import utils.FormatUtils;

/**
 * Man hinh bao cao: ket qua nap du lieu luc mo, top muon, qua han, doanh thu phat. Chi in.
 *
 * @author CuongThai Academy
 */
public class ReportView {

    // View khong giu du lieu
    public ReportView() {
    }

    // In ket qua nap: so ban ghi moi tep + tung dong hong
    public void showLoadReport(LoadReportDTO loadReport) {
        System.out.println(String.format(Message.LOAD_SUMMARY, loadReport.getItemCount(),
                loadReport.getMemberCount(), loadReport.getLoanCount()));

        // Co dong hong thi in so dong va tung cau bao
        if (!loadReport.getErrorList().isEmpty()) {
            System.out.println(String.format(Message.LOAD_ERROR_HEADER,
                    loadReport.getErrorList().size()));
            // Moi cau bao mot dong
            for (String error : loadReport.getErrorList()) {
                System.out.println(String.format(Message.LOAD_ERROR_LINE, error));
            }
        }
    }

    // In bang top tai lieu duoc muon nhieu nhat
    public void showTopItems(List<TopItemDTO> topList) {
        System.out.println(String.format(Message.TITLE_TOP, Constants.TOP_LIMIT));
        System.out.println(Message.TOP_TABLE_HEADER);

        // Moi tai lieu mot dong
        for (TopItemDTO row : topList) {
            System.out.println(String.format(Constants.TOP_ROW_FORMAT, row.getNo(),
                    row.getItemId(), row.getTypeName(),
                    FormatUtils.cut(row.getTitle(), Constants.TITLE_COLUMN), row.getLoanCount()));
        }
    }

    // In bang luot qua han tinh den ngay lam viec
    public void showOverdue(List<OverdueRowDTO> rowList, LocalDate workingDate) {
        System.out.println(String.format(Message.TITLE_OVERDUE,
                FormatUtils.formatDate(workingDate), rowList.size()));

        // Khong co luot qua han
        if (rowList.isEmpty()) {
            System.out.println(Message.NO_OVERDUE);
            return;
        }
        System.out.println(Message.OVERDUE_TABLE_HEADER);

        // Moi luot mot dong
        for (OverdueRowDTO row : rowList) {
            System.out.println(String.format(Constants.OVERDUE_ROW_FORMAT, row.getNo(),
                    row.getLoanId(), row.getMemberId(),
                    FormatUtils.cut(row.getMemberName(), Constants.NAME_COLUMN), row.getItemId(),
                    FormatUtils.cut(row.getTitle(), Constants.SHORT_TITLE_COLUMN),
                    FormatUtils.formatDate(row.getDueDate()), row.getDaysLate(),
                    FormatUtils.formatMoney(row.getEstimatedFine())));
        }
    }

    // In bang doanh thu phat theo thang + dong tong
    public void showRevenue(List<RevenueRowDTO> rowList, int total) {
        System.out.println(Message.TITLE_REVENUE);
        System.out.println(Message.REVENUE_TABLE_HEADER);

        // Tong so luot co phat
        int fineCount = 0;

        // Moi thang mot dong
        for (RevenueRowDTO row : rowList) {
            System.out.println(String.format(Constants.REVENUE_ROW_FORMAT, row.getMonth(),
                    row.getFineCount(), FormatUtils.formatMoney(row.getFineTotal())));
            fineCount += row.getFineCount();
        }
        System.out.println(String.format(Message.REVENUE_TOTAL, fineCount,
                FormatUtils.formatMoney(total)));
    }
}

