package constants;

/**
 * Moi HANG SO cua CT Library 1.0: lua chon menu, luat nghiep vu (han muon, phi tre, han muc,
 * muc khoa the), dinh dang ma / ngay / tien, tep du lieu va cot CSV, do rong bang. Doi mot
 * luat chi sua o day (khong viet so "thang" o lop nao khac).
 *
 * @author CuongThai Academy
 */
public final class Constants {

    // Ngan khong cho tao doi tuong Constants
    private Constants() {
    }

    // Lua chon menu: thoat
    public static final int MENU_EXIT = 0;

    // Lua chon menu: tim tai lieu theo ten
    public static final int MENU_SEARCH = 1;

    // Lua chon menu: them tai lieu
    public static final int MENU_ADD_ITEM = 2;

    // Lua chon menu: tra cuu the thanh vien
    public static final int MENU_MEMBER_CARD = 3;

    // Lua chon menu: them thanh vien
    public static final int MENU_ADD_MEMBER = 4;

    // Lua chon menu: muon tai lieu
    public static final int MENU_BORROW = 5;

    // Lua chon menu: tra tai lieu
    public static final int MENU_RETURN = 6;

    // Lua chon menu: dong tien phat
    public static final int MENU_PAY = 7;

    // Lua chon menu: bao cao top muon
    public static final int MENU_TOP = 8;

    // Lua chon menu: bao cao qua han
    public static final int MENU_OVERDUE = 9;

    // Lua chon menu: bao cao doanh thu phat
    public static final int MENU_REVENUE = 10;

    // Lua chon menu: doi ngay lam viec
    public static final int MENU_WORKING_DATE = 11;

    // Lua chon lon nhat cua menu
    public static final int MENU_LAST = MENU_WORKING_DATE;

    // Loai tai lieu: sach
    public static final int TYPE_BOOK = 1;

    // Loai tai lieu: tap chi
    public static final int TYPE_MAGAZINE = 2;

    // Loai tai lieu: DVD
    public static final int TYPE_DVD = 3;

    // Sach muon 14 ngay
    public static final int BOOK_LOAN_DAYS = 14;

    // Sach tre: 2000 dong/ngay
    public static final int BOOK_LATE_FEE = 2000;

    // Tap chi muon 7 ngay
    public static final int MAGAZINE_LOAN_DAYS = 7;

    // Tap chi tre: 1000 dong/ngay
    public static final int MAGAZINE_LATE_FEE = 1000;

    // DVD muon 3 ngay
    public static final int DVD_LOAN_DAYS = 3;

    // DVD tre: 5000 dong/ngay
    public static final int DVD_LATE_FEE = 5000;

    // Loai the: sinh vien
    public static final int MEMBER_STUDENT = 1;

    // Loai the: can bo
    public static final int MEMBER_STAFF = 2;

    // Sinh vien muon toi da 3 tai lieu cung luc
    public static final int STUDENT_MAX_LOANS = 3;

    // Can bo muon toi da 5 tai lieu cung luc
    public static final int STAFF_MAX_LOANS = 5;

    // No phat LON HON muc nay (dong) thi khoa the
    public static final int LOCK_DEBT_LIMIT = 50000;

    // Sinh vien duoc giam 50% phi tre
    public static final int STUDENT_DISCOUNT_PERCENT = 50;

    // Can bo duoc mien 2 ngay tre dau
    public static final int STAFF_FREE_DAYS = 2;

    // 100 phan tram
    public static final int PERCENT_FULL = 100;

    // So dong cua bao cao top
    public static final int TOP_LIMIT = 10;

    // So tien nop toi da mot lan (dong)
    public static final int AMOUNT_MAX = 10000000;

    // Tien to ma sach
    public static final String BOOK_ID_PREFIX = "B";

    // Tien to ma tap chi
