public class AppController {

    // Kho tai lieu dung chung
    private IBookRepository bookRepository;

    // Kho thanh vien dung chung
    private IMemberRepository memberRepository;

    // Kho luot muon dung chung
    private ILoanRepository loanRepository;

    // Dieu phoi tai lieu (tim, them)
    private BookController bookController;

    // Dieu phoi thanh vien (them)
    private MemberController memberController;

    // Dieu phoi muon - tra - no
    private LoanController loanController;

    // Dieu phoi bao cao
    private ReportController reportController;

    // Man hinh in ket qua nap
    private ReportView reportView;

    // Mo 3 kho (nap 3 tep), roi lap 4 Controller tren cung cac kho do
    public AppController() {
        bookRepository = new FileBookRepository(Constants.BOOK_FILE_PATH);
        memberRepository = new FileMemberRepository(Constants.MEMBER_FILE_PATH);
        loanRepository = new FileLoanRepository(Constants.LOAN_FILE_PATH);
