 * Luat muon: the bi KHOA vi no phat lon hon muc cho phep; dong phat roi moi muon tiep.
 *
 * @author CuongThai Academy
 */
public class MemberLockedException extends LibraryException {

    // Tao ngoai le kem cau bao loi tieng Viet da dien san ma, ten, so lieu
    public MemberLockedException(String message) {
        super(message);
    }
}

