package exceptions;

/**
 * Loi LUU TRU: doc/ghi tep du lieu that bai (o dia day, tep bi khoa, thu muc khong co quyen
 * ghi...). Kho tren tep boc IOException thanh loi nay kem cau bao tieng Viet noi ro tep nao,
 * giu IOException lam NGUYEN NHAN goc. Checked va thuoc ho LibraryException: Controller bat
 * cung cho voi loi nghiep vu, bao cho nguoi dung, menu chay tiep.
 *
 * @author CuongThai Academy
 */
public class StorageException extends LibraryException {

    // Tao ngoai le kem cau bao loi + nguyen nhan goc (thuong la IOException)
    public StorageException(String message, Throwable cause) {
        super(message, cause);
    }
}

package main;

import constants.Constants;
import constants.Message;
import controller.AppController;
import dto.BookRequestDTO;
import dto.LoanRequestDTO;
import dto.MemberRequestDTO;
import dto.PaymentRequestDTO;
import exceptions.InvalidInputException;
import java.time.LocalDate;
import java.util.Scanner;
import utils.FormatUtils;
import utils.Validation;

/**
 * Diem bat dau cua CT Library 1.0: lap rap chuong trinh (AppController mo 3 tep du lieu),
 * hoi ngay lam viec, in menu, doc va kiem moi o nhap (qua utils) roi goi Controller dung 1
 * lan. Main khong biet sach / thanh vien / luot muon nam o dau. Main chi bat
 * InvalidInputException (loi nhap — hoi lai); loi nghiep vu da duoc Controller bat.
 * Scanner mo bang try-with-resources nen tu dong dong khi thoat (khong System.exit).
 *
 * @author CuongThai Academy
 */
public final class Main {

    // Ngan khong cho tao doi tuong Main (Main chi co ham static)
    private Main() {
    }

    // Mo ban phim, lap rap chuong trinh, hoi ngay lam viec roi chay menu
    public static void main(String[] args) {
        // Scanner tu dong close() khi khoi try ket thuc
        try (Scanner scanner = new Scanner(System.in)) {
            AppController appController = new AppController();
            appController.showLoadReport();
            appController.setWorkingDate(getWorkingDate(scanner));
            runMenu(scanner, appController);
        }
    }

    // Lap menu den khi chon 0
    private static void runMenu(Scanner scanner, AppController appController) {
        // Co chay cua vong lap menu
        boolean isRunning = true;

        // Lap lai menu sau moi chuc nang
        while (isRunning) {
            System.out.println(Message.MENU_HEADER);
            System.out.println(Message.MENU_BODY);

            // Moi lua chon goi Controller dung 1 lan
            switch (getMenuChoice(scanner)) {
                // 1: tim tai lieu theo ten
                case Constants.MENU_SEARCH:
                    System.out.println(Message.TITLE_SEARCH);
                    appController.getBookController().searchItems(getKeyword(scanner));
                    break;
                // 2: them tai lieu
                case Constants.MENU_ADD_ITEM:
                    System.out.println(Message.TITLE_ADD_ITEM);
                    appController.getBookController().addItem(inputItem(scanner));
                    break;
                // 3: the thanh vien
                case Constants.MENU_MEMBER_CARD:
                    System.out.println(Message.TITLE_LOOKUP);
                    appController.getLoanController().showMemberCard(getMemberId(scanner));
                    break;
                // 4: them thanh vien
                case Constants.MENU_ADD_MEMBER:
                    System.out.println(Message.TITLE_ADD_MEMBER);
                    appController.getMemberController().addMember(inputMember(scanner));
                    break;
                // 5: muon
                case Constants.MENU_BORROW:
                    System.out.println(Message.TITLE_BORROW);
                    appController.getLoanController().borrowItem(inputLoan(scanner));
                    break;
                // 6: tra
                case Constants.MENU_RETURN:
                    System.out.println(Message.TITLE_RETURN);
                    appController.getLoanController().returnItem(inputLoan(scanner));
                    break;
                // 7: dong phat
                case Constants.MENU_PAY:
                    System.out.println(Message.TITLE_PAY);
                    appController.getLoanController().payFine(inputPayment(scanner));
                    break;
                // 8: top muon
                case Constants.MENU_TOP:
                    appController.getReportController().showTopBorrowed();
                    break;
                // 9: qua han
                case Constants.MENU_OVERDUE:
                    appController.getReportController().showOverdue();
                    break;
                // 10: doanh thu phat
                case Constants.MENU_REVENUE:
                    appController.getReportController().showRevenue();
                    break;
                // 11: doi ngay lam viec
                case Constants.MENU_WORKING_DATE:
                    appController.setWorkingDate(getWorkingDate(scanner));
                    break;
                // 0: thoat (du lieu da ghi sau MOI thay doi, khong can luu them)
                default:
                    System.out.println(Message.GOODBYE);
                    isRunning = false;
                    break;
            }
        }
    }

    // Hoi ngay lam viec: Enter = hom nay cua may, go ngay thi kiem chat; in lai ngay da chon
    private static LocalDate getWorkingDate(Scanner scanner) {
        // Lap den khi go dung (hoac Enter)
        while (true) {
            // In cau nhac, doc ca dong; rong thi lay hom nay
            try {
                System.out.print(Message.INPUT_WORKING_DATE);
                String input = scanner.nextLine();
                LocalDate workingDate = LocalDate.now();
                // Co go thi doi chu thanh ngay
                if (!input.trim().isEmpty()) {
                    workingDate = Validation.getDate(input);
                }
                System.out.println(String.format(Message.WORKING_DATE,
                        FormatUtils.formatDate(workingDate)));
                return workingDate;
            } catch (InvalidInputException e) {
                // Sai thi in cau bao loi roi hoi lai
                System.out.println(e.getMessage());
            }
        }
    }

    // Chon loai, nhap phan chung roi phan rieng cua loai do, gom vao 1 phieu DTO moi
    private static BookRequestDTO inputItem(Scanner scanner) {
        // Phieu moi; loai quyet dinh phai hoi them o nao
        BookRequestDTO bookRequestDTO = new BookRequestDTO();
        bookRequestDTO.setItemType(getItemType(scanner));
        bookRequestDTO.setTitle(getTitle(scanner));
        bookRequestDTO.setYear(getYear(scanner));
        bookRequestDTO.setCopies(getCopies(scanner));

        // Phan rieng: man hinh nhap la noi duy nhat (ngoai kho) can biet tung loai
        switch (bookRequestDTO.getItemType()) {
            // Sach: ISBN + tac gia
            case Constants.TYPE_BOOK:
                bookRequestDTO.setIsbn(getIsbn(scanner));
                bookRequestDTO.setAuthor(getAuthor(scanner));
                break;
            // Tap chi: ky so
            case Constants.TYPE_MAGAZINE:
                bookRequestDTO.setIssueNumber(getIssueNumber(scanner));
                break;
            // DVD: so phut
            default:
                bookRequestDTO.setMinutes(getMinutes(scanner));
                break;
        }
        return bookRequestDTO;
    }

    // Nhap loai the, ho ten, email vao 1 phieu
    private static MemberRequestDTO inputMember(Scanner scanner) {
