package model;

import constants.Constants;
import constants.Message;

/**
 * Mot cuon sach: LA MOT (is-a) tai lieu, them ISBN va tac gia.
 * Muon 14 ngay, tre 2000 dong/ngay, khoa chong trung la ISBN.
 * JavaBean: truong private, constructor rong public, getter/setter.
 *
 * @author CuongThai Academy
 */
public class Book extends LibraryItem {

    // Ma ISBN-13 (13 chu so, da bo dau - va dau cach)
    private String isbn;

    // Tac gia da chuan hoa (Title Case)
    private String author;

    // Constructor rong (JavaBean): goi constructor day du voi chuoi rong va so 0
    public Book() {
        this("", "", "", "", 0, 0);
    }

    // Constructor day du; super(...) PHAI la dong dau: dung phan cha truoc, phan con sau
    public Book(String id, String isbn, String title, String author, int year, int copies) {
        super(id, title, year, copies);
        this.isbn = isbn;
        this.author = author;
    }

    // Tra ve ISBN
    public String getIsbn() {
        return isbn;
    }

    // Gan ISBN
    public void setIsbn(String isbn) {
        this.isbn = isbn;
    }

    // Tra ve tac gia (ghi de cau tra loi mac dinh "khong co tac gia" cua LibraryItem)
    @Override
    public String getAuthor() {
        return author;
    }

    // Gan tac gia
    public void setAuthor(String author) {
        this.author = author;
    }

    // So cua loai: TYPE_BOOK
    @Override
    public int getItemType() {
        return Constants.TYPE_BOOK;
    }

    // Loai: Sach
    @Override
    public String getTypeName() {
        return Message.TYPE_BOOK;
    }

    // Ma sach bat dau bang B
    @Override
    public String getIdPrefix() {
        return Constants.BOOK_ID_PREFIX;
    }

    // Sach muon 14 ngay
    @Override
    public int getLoanDays() {
        return Constants.BOOK_LOAN_DAYS;
    }

    // Sach tre 2000 dong/ngay
    @Override
    public int getLateFeePerDay() {
        return Constants.BOOK_LATE_FEE;
    }

    // Chi tiet: tac gia + ISBN
    @Override
    public String getDetail() {
        return String.format(Message.DETAIL_BOOK, author, isbn);
    }

    // Hai cuon cung ISBN la trung
    @Override
    public String getUniqueKey() {
        return String.format(Message.KEY_BOOK, isbn);
    }

    // Cot rieng cua sach trong tep: ISBN roi tac gia
    @Override
    public String[] getExtraValueArray() {
        return new String[] {isbn, author};
    }
}

package model;

import constants.Constants;
import constants.Message;

/**
 * Mot dia DVD: LA MOT tai lieu, them thoi luong (phut).
 * Muon 3 ngay, tre 5000 dong/ngay; trung khi cung ten va cung nam.
 * Ten lop viet Dvd (khong phai DVD): tu viet tat cung viet nhu mot tu, giong Id (khong ID).
 *
 * @author CuongThai Academy
 */
public class Dvd extends LibraryItem {

    // Thoi luong (phut, 1 den 600)
    private int minutes;

    // Constructor rong (JavaBean): goi constructor day du voi chuoi rong va so 0
    public Dvd() {
        this("", "", 0, 0, 0);
    }

    // Constructor day du; super(...) dung phan cha truoc
    public Dvd(String id, String title, int year, int copies, int minutes) {
        super(id, title, year, copies);
        this.minutes = minutes;
    }

    // Tra ve so phut
    public int getMinutes() {
        return minutes;
    }

    // Gan so phut
    public void setMinutes(int minutes) {
        this.minutes = minutes;
    }

    // So cua loai: TYPE_DVD
    @Override
    public int getItemType() {
        return Constants.TYPE_DVD;
    }

    // Loai: DVD
    @Override
    public String getTypeName() {
        return Message.TYPE_DVD;
    }

    // Ma DVD bat dau bang D
    @Override
    public String getIdPrefix() {
        return Constants.DVD_ID_PREFIX;
    }

    // DVD muon 3 ngay
    @Override
    public int getLoanDays() {
        return Constants.DVD_LOAN_DAYS;
    }

    // DVD tre 5000 dong/ngay
    @Override
    public int getLateFeePerDay() {
        return Constants.DVD_LATE_FEE;
    }

    // Chi tiet: so phut
    @Override
    public String getDetail() {
        return String.format(Message.DETAIL_DVD, minutes);
    }

    // Cung ten + cung nam la trung
    @Override
    public String getUniqueKey() {
        return String.format(Message.KEY_DVD, getTitle(), getYear());
    }

    // Cot rieng cua DVD trong tep: so phut
    @Override
    public String[] getExtraValueArray() {
        return new String[] {String.valueOf(minutes)};
    }
}

package model;

import constants.Constants;

/**
 * Lop CHA TRUU TUONG (abstract) cua moi tai lieu: sach, tap chi, DVD (Lab 5).
 * Khong ai tao duoc "mot tai lieu chung chung" (new LibraryItem() la loi bien dich);
 * phan chung (ma, ten, nam, so ban) viet MOT lan o day, con 6 phuong thuc truu tuong
 * la HOP DONG: lop con nao khong cai du thi javac khong cho chay.
 *
 * @author CuongThai Academy
 */
public abstract class LibraryItem {

    // Ma tai lieu do kho cap (B001, T005, D006...)
    private String id;

    // Ten da chuan hoa (Title Case)
    private String title;

    // Nam xuat ban / phat hanh
    private int year;

    // So ban dang co tren ke
    private int copies;

    // Constructor phan chung; lop truu tuong VAN co constructor: lop con goi qua super(...)
    protected LibraryItem(String id, String title, int year, int copies) {
        this.id = id;
        this.title = title;
        this.year = year;
        this.copies = copies;
    }

    // Tra ve ma tai lieu
    public String getId() {
        return id;
    }

    // Gan ma tai lieu
    public void setId(String id) {
        this.id = id;
    }

    // Tra ve ten
    public String getTitle() {
        return title;
    }

    // Gan ten
    public void setTitle(String title) {
        this.title = title;
    }

    // Tra ve nam
    public int getYear() {
        return year;
    }

    // Gan nam
    public void setYear(int year) {
        this.year = year;
    }

    // Tra ve so ban
    public int getCopies() {
        return copies;
    }

    // Gan so ban
    public void setCopies(int copies) {
        this.copies = copies;
    }

    // So cua loai (TYPE_BOOK, TYPE_MAGAZINE, TYPE_DVD) — loc theo loai bang DA HINH,
    // khong can hoi "ban la instanceof lop nao" (Lab 7)
    public abstract int getItemType();

    // Ten loai tai lieu ("Sach", "Tap chi", "DVD") — moi lop con BUOC phai tra loi
    public abstract String getTypeName();

    // Chu cai dau cua ma (B, T, D)
    public abstract String getIdPrefix();

    // So ngay duoc muon
    public abstract int getLoanDays();

    // Phi tre moi ngay (dong)
    public abstract int getLateFeePerDay();

    // Thong tin rieng cua tung loai (tac gia + ISBN, ky so, so phut)
    public abstract String getDetail();

    // Khoa chong trung (2 tai lieu cung khoa la trung)
    public abstract String getUniqueKey();

    // Cac gia tri RIENG cua loai, dung thu tu cot trong tep CSV (Lab 9): sach {ISBN, tac gia},
    // tap chi {ky so}, DVD {so phut}. Kho tren tep ghi ma khong can hoi "ban la lop nao"
    public abstract String[] getExtraValueArray();

    // Tac gia (Lab 8, cho bao cao tac gia): tap chi va DVD khong co tac gia nen tra chuoi
    // rong; chi Book ghi de. Khong abstract: day la cau tra loi MAC DINH dung cho da so lop con
    public String getAuthor() {
        return Constants.NO_AUTHOR;
    }
}

