/**
 * Mot LUOT MUON (CT Library 1.0): ai muon gi, ngay muon, han tra, ngay tra that va tien phat.
 * Luot DANG MO = chua tra (returnDate la null). Tien phat duoc TINH MOT LAN luc tra roi GHI
 * LAI vao tep: doi chinh sach phi sau nay khong lam doi lich su da thu.
 * JavaBean: truong private, constructor rong public, getter/setter.
 *
 * @author CuongThai Academy
 */
public class Loan {

    // Ma luot muon do kho cap (L0001, L0002, ...)
    private String id;

    // Ma thanh vien muon (M001, ...)
    private String memberId;

    // Ma tai lieu duoc muon (B001, T151, D181, ...)
    private String itemId;

    // Ngay muon
    private LocalDate borrowDate;

    // Han tra = ngay muon + so ngay muon cua loai tai lieu
    private LocalDate dueDate;

    // Ngay tra that; null khi chua tra (luot dang mo)
    private LocalDate returnDate;

    // Tien phat da tinh luc tra (dong); 0 khi tra dung han hoac chua tra
    private int fine;

    // Constructor rong (JavaBean)
    public Loan() {
        this("", "", "");
    }

    // Constructor luot muon moi (chua co ngay): kho cap ma, Service dien ngay
    public Loan(String id, String memberId, String itemId) {
        this.id = id;
        this.memberId = memberId;
        this.itemId = itemId;
        this.fine = 0;
    }

    // Tra ve ma luot muon
    public String getId() {
        return id;
    }

    // Gan ma luot muon
    public void setId(String id) {
        this.id = id;
    }

    // Tra ve ma thanh vien
    public String getMemberId() {
        return memberId;
    }

    // Gan ma thanh vien
    public void setMemberId(String memberId) {
        this.memberId = memberId;
    }

    // Tra ve ma tai lieu
    public String getItemId() {
        return itemId;
    }

    // Gan ma tai lieu
    public void setItemId(String itemId) {
        this.itemId = itemId;
    }

    // Tra ve ngay muon
    public LocalDate getBorrowDate() {
        return borrowDate;
    }

    // Gan ngay muon
    public void setBorrowDate(LocalDate borrowDate) {
        this.borrowDate = borrowDate;
    }

    // Tra ve han tra
    public LocalDate getDueDate() {
        return dueDate;
    }

    // Gan han tra
    public void setDueDate(LocalDate dueDate) {
        this.dueDate = dueDate;
    }

    // Tra ve ngay tra that (null = chua tra)
    public LocalDate getReturnDate() {
        return returnDate;
    }

    // Gan ngay tra that
    public void setReturnDate(LocalDate returnDate) {
        this.returnDate = returnDate;
    }

    // Tra ve tien phat da tinh
    public int getFine() {
        return fine;
    }

    // Gan tien phat da tinh
    public void setFine(int fine) {
        this.fine = fine;
    }

    // Luot dang mo = chua co ngay tra
    public boolean isOpen() {
        return returnDate == null;
    }
}

