package model;

/**
 * Lop CHA TRUU TUONG cua moi thanh vien cau lac bo (CT Library 1.0): sinh vien hoac can bo.
 * Phan chung (ma, ho ten, email, no phat) viet MOT lan o day; cau hoi "loai the nay duoc muon
 * toi da bao nhieu" la HOP DONG (abstract) — moi lop con tu tra loi, Service khong can if theo
 * loai. JavaBean: truong private, getter/setter; lop con co constructor rong public.
 *
 * @author CuongThai Academy
 */
public abstract class Member {

    // Ma thanh vien do kho cap (M001, M002, ...)
    private String id;

    // Ho ten da chuan hoa (Title Case, khong dau)
    private String name;

    // Email lien lac (da viet thuong)
    private String email;

    // Tien phat CON NO (dong); lon hon muc khoa the thi khong duoc muon
    private int debt;

    // Constructor phan chung; lop con goi qua super(...)
    protected Member(String id, String name, String email, int debt) {
        this.id = id;
        this.name = name;
        this.email = email;
        this.debt = debt;
    }

    // Tra ve ma thanh vien
    public String getId() {
        return id;
    }

    // Gan ma thanh vien
    public void setId(String id) {
        this.id = id;
    }

    // Tra ve ho ten
    public String getName() {
        return name;
    }

    // Gan ho ten
    public void setName(String name) {
        this.name = name;
    }

    // Tra ve email
    public String getEmail() {
        return email;
    }

    // Gan email
    public void setEmail(String email) {
        this.email = email;
    }

    // Tra ve tien phat con no
    public int getDebt() {
        return debt;
    }

    // Gan tien phat con no
    public void setDebt(int debt) {
        this.debt = debt;
    }

    // So cua loai the (MEMBER_STUDENT, MEMBER_STAFF) — cot "loai" trong tep members.csv
    public abstract int getMemberType();

    // Ten loai the ("Sinh vien", "Can bo")
    public abstract String getTypeName();

    // So tai lieu duoc muon CUNG LUC toi da
    public abstract int getMaxLoans();
}

