import exceptions.InvalidInputException;
import exceptions.LibraryException;
import exceptions.MemberNotFoundException;
import exceptions.StorageException;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import model.Member;
import model.StaffMember;
import model.StudentMember;
import utils.CsvUtils;
import utils.Validation;

/**
 * Kho thanh vien tren tep data/members.csv (UTF-8): loai the, ma, ho ten, email, no phat.
 * Cung khuon voi FileBookRepository: nap tung dong qua Validation (dong hong bo qua + so
 * dong), moi thay doi ghi lai ca tep qua tep tam. Email khong duoc trung (HashSet).
 *
 * @author CuongThai Academy
 */
public class FileMemberRepository implements IMemberRepository {

    // Thanh vien theo ma, giu thu tu
    private Map<String, Member> memberMap;

    // Email da dung (chong trung)
    private Set<String> emailSet;

    // Duong dan tep du lieu
    private String filePath;

    // Cau bao luc nap
    private List<String> loadErrorList;

    // Nap thay dong hong ma chua sao luu
    private boolean isBackupNeeded;

    // So lon nhat da cap
    private int lastNumber;

    // Tao kho tren tep va nap ngay
    public FileMemberRepository(String filePath) {
        this.filePath = filePath;
        memberMap = new LinkedHashMap<>();
        emailSet = new HashSet<>();
        loadErrorList = new ArrayList<>();
        isBackupNeeded = false;
        lastNumber = 0;
        loadFromFile();
    }

    // Moi thanh vien (ban sao)
    @Override
    public List<MemberResponseDTO> findAll() {
        // Danh sach ban sao
        List<MemberResponseDTO> resultList = new ArrayList<>();

        // Doi tung model thanh DTO
        for (Member member : memberMap.values()) {
            resultList.add(toResponse(member));
        }
        return resultList;
    }

    // Tim theo ma bang HashMap
    @Override
    public MemberResponseDTO findById(String id) throws MemberNotFoundException {
        return toResponse(findMember(id));
    }

    // Them thanh vien moi (no 0): kiem trung email, cap ma, ghi lai tep
    @Override
    public String addMember(MemberRequestDTO memberRequestDTO)
            throws DuplicateKeyException, StorageException {
        // Trung email thi tu choi
        if (emailSet.contains(memberRequestDTO.getEmail())) {
            throw new DuplicateKeyException(String.format(Message.ERROR_DUPLICATE_EMAIL,
                    memberRequestDTO.getEmail()));
        }

        // Cap ma, dung model dung loai the, them
        lastNumber++;
        Member member = createMember(memberRequestDTO.getMemberType());
        member.setId(String.format(Constants.MEMBER_ID_FORMAT, lastNumber));
        member.setName(memberRequestDTO.getName());
        member.setEmail(memberRequestDTO.getEmail());
        member.setDebt(0);
        memberMap.put(member.getId(), member);
        emailSet.add(member.getEmail());
        saveToFile();
        return member.getId();
    }

    // Ghi no phat moi roi ghi lai tep
    @Override
    public void updateDebt(String id, int debt) throws MemberNotFoundException,
            StorageException {
        findMember(id).setDebt(debt);
        saveToFile();
    }

    // So thanh vien
    @Override
    public int countMembers() {
        return memberMap.size();
    }

    // Cau bao luc nap (ban sao)
    @Override
    public List<String> findLoadErrorList() {
        return new ArrayList<>(loadErrorList);
    }

    // Tim model theo ma; khong co thi nem loi kem ma
    private Member findMember(String id) throws MemberNotFoundException {
        // Thanh vien mang ma nay (null neu khong co)
        Member member = memberMap.get(id);

        // Khong co ma thi bao
        if (member == null) {
            throw new MemberNotFoundException(String.format(Message.ERROR_MEMBER_NOT_FOUND, id));
        }
        return member;
    }

    // Nap tep: moi dong mot khoi try
    private void loadFromFile() {
        // Doc moi dong; loi doc that thi ghi cau bao
        try {
            // Cac dong du lieu da tach
            List<CsvRowDTO> rowList = CsvUtils.readRows(filePath, loadErrorList);

            // Doi tung dong thanh model
            for (CsvRowDTO row : rowList) {
                // Dong hong: 1 cau bao kem so dong
                try {
                    loadRow(row);
                } catch (LibraryException e) {
                    // Bo qua dong nay
                    loadErrorList.add(String.format(Message.ERROR_CSV_LINE, filePath,
                            row.getLineNumber(), e.getMessage()));
                    isBackupNeeded = true;
                }
            }
        } catch (StorageException e) {
            // Khong doc duoc tep: kho rong
            loadErrorList.add(e.getMessage());
        }
    }

    // Doi 1 dong tep thanh model qua Validation
    private void loadRow(CsvRowDTO row) throws InvalidInputException, DuplicateKeyException {
        // Cac gia tri cua dong
        List<String> valueList = row.getValueList();

        // Dung so cot
        if (valueList.size() != Constants.MEMBER_CSV_COLUMNS) {
            throw new InvalidInputException(String.format(Message.ERROR_CSV_COLUMNS,
                    Constants.MEMBER_CSV_COLUMNS, valueList.size()));
        }

        // Tung cot qua bo kiem cua ban phim
        Member member = createMember(Validation.getMemberType(
                valueList.get(Constants.MEMBER_CSV_TYPE_INDEX)));
        member.setId(Validation.getMemberId(valueList.get(Constants.MEMBER_CSV_ID_INDEX)));
        member.setName(Validation.getMemberName(valueList.get(Constants.MEMBER_CSV_NAME_INDEX)));
        member.setEmail(Validation.getEmail(valueList.get(Constants.MEMBER_CSV_EMAIL_INDEX)));
        member.setDebt(Validation.getNonNegative(valueList.get(Constants.MEMBER_CSV_DEBT_INDEX),
                Message.FIELD_DEBT));

        // Trung ma hoac trung email thi bo dong
        if (memberMap.containsKey(member.getId())) {
            throw new DuplicateKeyException(String.format(Message.ERROR_DUPLICATE_ID,
                    member.getId()));
        }

        // Email da co o dong truoc
        if (emailSet.contains(member.getEmail())) {
            throw new DuplicateKeyException(String.format(Message.ERROR_DUPLICATE_EMAIL,
                    member.getEmail()));
        }
        memberMap.put(member.getId(), member);
        emailSet.add(member.getEmail());
        lastNumber = Math.max(lastNumber, Integer.parseInt(member.getId().substring(
                Constants.ID_PREFIX_LENGTH)));
    }

    // Loai the -> model dung lop con (noi DUY NHAT hoi loai the)
    private Member createMember(int memberType) {
        // Can bo hay sinh vien
        if (memberType == Constants.MEMBER_STAFF) {
            return new StaffMember();
        }
        return new StudentMember();
    }

    // Ghi lai ca tep
    private void saveToFile() throws StorageException {
        // Lan ghi dau sau khi nap thay dong hong: giu tep goc
        if (isBackupNeeded) {
            CsvUtils.backupFile(filePath);
            isBackupNeeded = false;
        }

        // Moi thanh vien thanh 1 dong CSV
        List<String> lineList = new ArrayList<>();
        for (Member member : memberMap.values()) {
            // Gia tri cac cot theo dong tieu de
            List<String> valueList = new ArrayList<>();
            valueList.add(String.valueOf(member.getMemberType()));
            valueList.add(member.getId());
            valueList.add(member.getName());
            valueList.add(member.getEmail());
            valueList.add(String.valueOf(member.getDebt()));
            lineList.add(CsvUtils.joinLine(valueList));
        }
        CsvUtils.writeRows(filePath, Constants.MEMBER_CSV_HEADER, lineList);
    }

    // Model -> ban sao DTO (han muc lay tu cau tra loi da hinh cua lop con)
    private MemberResponseDTO toResponse(Member member) {
        // Dong ban sao
        MemberResponseDTO response = new MemberResponseDTO();
        response.setId(member.getId());
        response.setMemberType(member.getMemberType());
        response.setTypeName(member.getTypeName());
        response.setName(member.getName());
        response.setEmail(member.getEmail());
        response.setDebt(member.getDebt());
        response.setMaxLoans(member.getMaxLoans());
        return response;
    }
}

